export const EVM_SWAP_KIND = 'evm.swap_exact_input.v1';

function checkStoredEvmArtifactVerification(stored, decoded) {
  if (stored.artifact_format !== 'eip1559') return { ok: false, detail: 'artifact-verify format is not eip1559' };
  if (stored.native_transaction_hash !== decoded.native_transaction_hash || stored.unsigned_hash !== decoded.unsigned_hash) {
    return { ok: false, detail: 'artifact-verify transaction hash differs from raw transaction' };
  }
  if (stored.signer_pubkey !== decoded.recovered_public_key || stored.local_verify?.ok !== true ||
      !addressEqEvm(stored.local_verify?.derivedAddressHex, decoded.recovered_sender)) {
    return { ok: false, detail: 'artifact-verify signer differs from recovered raw-transaction signer' };
  }
  const d = stored.decoded_transaction;
  if (!d || d.type !== 2 || d.chain_id !== decoded.chain_id || d.nonce !== decoded.nonce || d.value !== decoded.value ||
      d.data !== decoded.data || d.native_transaction_hash !== decoded.native_transaction_hash ||
      !addressEqEvm(d.to, decoded.to) || !addressEqEvm(d.recovered_sender, decoded.recovered_sender)) {
    return { ok: false, detail: 'artifact-verify decoded transaction differs from raw transaction' };
  }
  const call = d.call;
  if (!call || !addressEqEvm(String(call.token_in ?? ''), decoded.call.token_in) ||
      !addressEqEvm(String(call.token_out ?? ''), decoded.call.token_out) ||
      !addressEqEvm(String(call.recipient ?? ''), decoded.call.recipient) || call.fee !== decoded.call.fee ||
      call.deadline !== decoded.call.deadline || call.amount_in !== decoded.call.amount_in ||
      call.amount_out_minimum !== decoded.call.amount_out_minimum || call.sqrt_price_limit_x96 !== decoded.call.sqrt_price_limit_x96) {
    return { ok: false, detail: 'artifact-verify decoded calldata differs from raw transaction' };
  }
  return { ok: true };
}

const evmSwapDomain = {
  kind: EVM_SWAP_KIND,

  deriveDomainBlock(view) {
    const mandate = view.mandate;
    const p = mandate ? mandate.action.params : null;
    const intentP = view.intentParsed?.action?.params;
    const preflightRaw = view.readEvidence('evm-preflight.json');
    const quoteRaw = view.readEvidence('evm-quote.json');
    const verifyRaw = view.readEvidence(ARTIFACT_VERIFY_FILE);
    const finalRaw = view.readEvidence('evm-settlement-final.json');
    const settlementRef = finalRaw ? JSON.parse(finalRaw).settlement_ref : null;
    const preflight = preflightRaw ? JSON.parse(preflightRaw) : null;
    const quote = quoteRaw ? JSON.parse(quoteRaw) : null;
    const artifactVerify = verifyRaw ? JSON.parse(verifyRaw) : null;
    return {
      venue_id: p?.venue?.venue_id ?? null,
      chain_id: p?.venue?.chain?.chain_id ?? null,
      genesis_block_hash: p?.venue?.chain?.genesis_block_hash ?? null,
      pool: p?.venue?.pool?.address ?? null,
      router: p?.venue?.router?.address ?? null,
      quoter: p?.venue?.quoter?.address ?? null,
      token_in: p?.venue?.token_in?.weth ?? null,
      token_out: p?.venue?.token_out?.address ?? null,
      recipient: p?.recipient ?? null,
      amount_in_wei: p?.amount_in_wei ?? intentP?.amount_in_wei ?? null,
      amount_out_minimum: quote?.amount_out_minimum ?? null,
      preflight_block_number: preflight?.trust?.block_number ?? null,
      transaction_hash: artifactVerify?.native_transaction_hash ?? null,
      settlement_ref: settlementRef,
    };
  },

  requiredFiles(outcome, _mode) {
    const base = [...CORE_EVIDENCE_BASE];
    const policyStage = ['mandate.json', 'mandate.sig.json', 'policy-decision.json', 'evm-venue.json', 'evm-policy-context.json'];
    const executionStage = [ARTIFACT_FILE, ARTIFACT_VERIFY_FILE, 'evm-preflight.json', 'evm-quote.json', 'evm-simulation.json'];
    switch (outcome) {
      case 'INVALID_INTENT':
        return { required: [...base, 'intake-decision.json'], forbidden: ['mandate.json', ARTIFACT_FILE, 'submit-result.json'] };
      case 'POLICY_REJECTED':
        return { required: [...base, ...policyStage], forbidden: [...executionStage, 'submit-result.json', 'settlement-observations.jsonl'] };
      case 'EXPIRED':
        return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: ['submit-result.json'] };
      case 'HALTED':
        return { required: base, forbidden: [] };
      case 'EXECUTION_FAILED':
        return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
      case 'SHADOW_COMPLETED':
        return { required: [...base, ...policyStage, ...executionStage], forbidden: ['arm-consumed.json', 'submit-result.json', 'settlement-observations.jsonl'] };
      case 'EXECUTED':
        return { required: [...base, ...policyStage, ...executionStage, 'arm-consumed.json', 'submit-result.json', 'settlement-observations.jsonl', 'evm-settlement-final.json'], forbidden: [] };
      case 'NO_COUNTERPARTY':
        return { required: base, forbidden: [] };
    }
  },

  allowedOutcomes: ['SHADOW_COMPLETED', 'EXECUTED', 'INVALID_INTENT', 'POLICY_REJECTED', 'EXPIRED', 'HALTED', 'EXECUTION_FAILED'],

  async checkArtifact({ artifactHex, mandate, evidenceDir }) {
    if (!mandate) return { ok: false, detail: 'EVM artifact requires mandate.json' };
    try {
      const preflight = JSON.parse(readFileSync(join(evidenceDir, 'evm-preflight.json'), 'utf8'));
      const quote = JSON.parse(readFileSync(join(evidenceDir, 'evm-quote.json'), 'utf8'));
      const simulation = JSON.parse(readFileSync(join(evidenceDir, 'evm-simulation.json'), 'utf8'));
      const stored = JSON.parse(readFileSync(join(evidenceDir, ARTIFACT_VERIFY_FILE), 'utf8'));
      const verdict = verifyEvmArtifactStandalone({ artifactHex, mandate, preflight, quote, simulation });
      if (!verdict.ok) return { ok: false, detail: verdict.detail };
      return checkStoredEvmArtifactVerification(stored, verdict.decoded);
    } catch (err) {
      return { ok: false, detail: `EVM artifact evidence invalid: ${String(err)}` };
    }
  },

  checkOutcomeExtensions({ stmt, evidenceDir }) {
    if (stmt.outcome === 'SHADOW_COMPLETED') {
      if (stmt.domain?.settlement_ref != null) return { ok: false, detail: 'EVM shadow must not carry settlement evidence' };
      const verified = JSON.parse(readFileSync(join(evidenceDir, ARTIFACT_VERIFY_FILE), 'utf8'));
      if (verified.local_verify?.ok !== true) return { ok: false, detail: 'EVM shadow requires local transaction verification' };
    }
    if (stmt.outcome === 'EXECUTED') {
      if (stmt.domain?.settlement_ref == null) return { ok: false, detail: 'EVM EXECUTED requires settlement_ref' };
      const submit = JSON.parse(readFileSync(join(evidenceDir, 'submit-result.json'), 'utf8'));
      if (submit.ok !== true || submit.attempts !== 1) return { ok: false, detail: 'EVM EXECUTED requires exactly one accepted submit attempt' };
      const mandate = JSON.parse(readFileSync(join(evidenceDir, 'mandate.json'), 'utf8'));
      const final = JSON.parse(readFileSync(join(evidenceDir, 'evm-settlement-final.json'), 'utf8'));
      // Re-derive the prepared transaction from the case's own execution
      // evidence, so EXECUTED can only mean: the settled transaction IS the
      // exact signed artifact of this case (Gate C HIGH 2).
      const normative = deriveNormativePreparedStandalone({
        mandate,
        artifactHex: readFileSync(join(evidenceDir, ARTIFACT_FILE), 'utf8').trim(),
        preflight: JSON.parse(readFileSync(join(evidenceDir, 'evm-preflight.json'), 'utf8')),
        quote: JSON.parse(readFileSync(join(evidenceDir, 'evm-quote.json'), 'utf8')),
        simulation: JSON.parse(readFileSync(join(evidenceDir, 'evm-simulation.json'), 'utf8')),
      });
      if (!normative.ok) return { ok: false, detail: `EVM settled artifact is not verifiable: ${normative.detail}` };
      const settlementError = verifyEvmFinalSettlementStandalone(mandate, final, normative.prepared);
      if (settlementError) return { ok: false, detail: settlementError };
      if (canonicalize(stmt.domain.settlement_ref) !== canonicalize(final.settlement_ref)) return { ok: false, detail: 'receipt settlement_ref differs from final settlement evidence' };
      // settlement_ref.transaction_hash == receipt domain transaction_hash
      // == verified artifact native transaction hash, all three.
      const settledHash = String(final.settlement_ref?.transaction_hash ?? '').toLowerCase();
      if (String(stmt.domain.transaction_hash ?? '').toLowerCase() !== settledHash) return { ok: false, detail: 'receipt transaction_hash differs from the settled transaction hash' };
      if (settledHash !== normative.prepared.tx_hash) return { ok: false, detail: 'settled transaction hash differs from the verified artifact transaction hash' };
    }
    return { ok: true };
  },
};

