const LP_MAX_UINT128 = ((1n << 128n) - 1n).toString();
const LP_FULL_RANGE_TICK_LOWER = -887220;
const LP_FULL_RANGE_TICK_UPPER = 887220;
const LP_Q96 = 1n << 96n;
const LP_MAX_UINT256 = (1n << 256n) - 1n;

const LP_TICK_MAGIC = [
  [0x2n, 0xfff97272373d413259a46990580e213an],
  [0x4n, 0xfff2e50f5f656932ef12357cf3c7fdccn],
  [0x8n, 0xffe5caca7e10e4e61c3624eaa0941cd0n],
  [0x10n, 0xffcb9843d60f6159c9db58835c926644n],
  [0x20n, 0xff973b41fa98c081472e6896dfb254c0n],
  [0x40n, 0xff2ea16466c96a3843ec78b326b52861n],
  [0x80n, 0xfe5dee046a99a2a811c461f1969c3053n],
  [0x100n, 0xfcbe86c7900a88aedcffc83b479aa3a4n],
  [0x200n, 0xf987a7253ac413176f2b074cf7815e54n],
  [0x400n, 0xf3392b0822b70005940c7a398e4b70f3n],
  [0x800n, 0xe7159475a2c29b7443b29c7fa6e889d9n],
  [0x1000n, 0xd097f3bdfd2022b8845ad8f792aa5825n],
  [0x2000n, 0xa9f746462d870fdf8a65dc1f90e061e5n],
  [0x4000n, 0x70d869a156d2a1b890bb3df62baf32f7n],
  [0x8000n, 0x31be135f97d08fd981231505542fcfa6n],
  [0x10000n, 0x9aa508b5b7a84e1c677de54f3e99bc9n],
  [0x20000n, 0x5d6af8dedb81196699c329225ee604n],
  [0x40000n, 0x2216e584f5fa1ea926041bedfe98n],
  [0x80000n, 0x48a170391f7dc42444e8fa2n],
];

function lpGetSqrtRatioAtTick(tick) {
  if (!Number.isInteger(tick) || Math.abs(tick) > 887272) throw new Error(`tick out of range: ${tick}`);
  const absTick = BigInt(Math.abs(tick));
  let ratio = (absTick & 1n) !== 0n ? 0xfffcb933bd6fad37aa2d162d1a594001n : 0x100000000000000000000000000000000n;
  for (const [bit, magic] of LP_TICK_MAGIC) {
    if ((absTick & bit) !== 0n) ratio = (ratio * magic) >> 128n;
  }
  if (tick > 0) ratio = LP_MAX_UINT256 / ratio;
  return (ratio >> 32n) + ((ratio & ((1n << 32n) - 1n)) > 0n ? 1n : 0n);
}

const LP_SQRT_LOWER = lpGetSqrtRatioAtTick(LP_FULL_RANGE_TICK_LOWER);
const LP_SQRT_UPPER = lpGetSqrtRatioAtTick(LP_FULL_RANGE_TICK_UPPER);

function lpMulDivFloor(a, b, denominator) {
  if (denominator <= 0n) throw new Error('mulDiv: non-positive denominator');
  return (a * b) / denominator;
}

function lpMulDivRoundingUp(a, b, denominator) {
  if (denominator <= 0n) throw new Error('mulDiv: non-positive denominator');
  const product = a * b;
  return product / denominator + (product % denominator > 0n ? 1n : 0n);
}

function lpAmount0RoundUp(liquidity, sqrtP) {
  const numerator = lpMulDivRoundingUp(liquidity << 96n, LP_SQRT_UPPER - sqrtP, LP_SQRT_UPPER);
  return numerator / sqrtP + (numerator % sqrtP > 0n ? 1n : 0n);
}

function lpAmount1RoundUp(liquidity, sqrtP) {
  return lpMulDivRoundingUp(liquidity, sqrtP - LP_SQRT_LOWER, LP_Q96);
}

function lpDeriveFullRangeOpenAmounts({ sqrtPriceX96, maxWethInWei, maxSupraInWei, minOutBps }) {
  const sqrtP = sqrtPriceX96;
  if (sqrtP <= LP_SQRT_LOWER || sqrtP >= LP_SQRT_UPPER) throw new Error('pool sqrtPriceX96 outside the full range');
  if (maxWethInWei <= 0n || maxSupraInWei <= 0n) throw new Error('caps must be positive');
  if (!Number.isInteger(minOutBps) || minOutBps <= 0 || minOutBps >= 10000) throw new Error('minOutBps must be an integer in (0, 10000)');
  const liquidityFromWeth = lpMulDivFloor(maxWethInWei, lpMulDivFloor(sqrtP, LP_SQRT_UPPER, LP_Q96), LP_SQRT_UPPER - sqrtP);
  const liquidityFromSupra = lpMulDivFloor(maxSupraInWei, LP_Q96, sqrtP - LP_SQRT_LOWER);
  let liquidity = liquidityFromWeth < liquidityFromSupra ? liquidityFromWeth : liquidityFromSupra;
  if (liquidity <= 0n) throw new Error('caps yield zero liquidity');
  let amount0 = 0n;
  let amount1 = 0n;
  for (let attempt = 0; ; attempt++) {
    amount0 = lpAmount0RoundUp(liquidity, sqrtP);
    amount1 = lpAmount1RoundUp(liquidity, sqrtP);
    if (amount0 <= maxWethInWei && amount1 <= maxSupraInWei) break;
    if (attempt >= 3 || liquidity <= 1n) throw new Error('cap-respecting liquidity derivation did not converge');
    liquidity -= 1n;
  }
  if (amount0 <= 0n || amount1 <= 0n) throw new Error('derived desired amounts must be positive');
  const bps = BigInt(minOutBps);
  return {
    sqrt_price_x96: sqrtP.toString(),
    liquidity: liquidity.toString(),
    amount0_desired: amount0.toString(),
    amount1_desired: amount1.toString(),
    amount0_min: ((amount0 * bps) / 10000n).toString(),
    amount1_min: ((amount1 * bps) / 10000n).toString(),
  };
}

// EIP-55 checksum without ethers (used where the TS side renders getAddress()).
function lpChecksumAddress(value) {
  const hex = String(value).toLowerCase().replace(/^0x/, '');
  if (!/^[0-9a-f]{40}$/.test(hex)) throw new Error('address malformed');
  const hash = Buffer.from(__keccak256(Buffer.from(hex, 'ascii'))).toString('hex');
  let out = '0x';
  for (let i = 0; i < 40; i++) out += parseInt(hash[i], 16) >= 8 ? hex[i].toUpperCase() : hex[i];
  return out;
}

// -- LP transaction-level decode (parallel to the swap decoder; the swap
// decoder stays byte-frozen and exactInputSingle-only) ----------------------
function decodeLpTransactionStandalone(artifactHex) {
  try {
    if (typeof artifactHex !== 'string' || !/^[0-9a-f]+$/.test(artifactHex) || artifactHex.length % 2) {
      return { ok: false, detail: 'raw transaction must be lowercase even-length hex' };
    }
    const raw = Buffer.from(artifactHex, 'hex');
    if (raw[0] !== 2) return { ok: false, detail: 'raw transaction must be canonical EIP-1559 type 2' };
    const parsed = rlpDecodeAt(raw, 1);
    if (parsed.next !== raw.length || !Array.isArray(parsed.node) || parsed.node.length !== 12) {
      return { ok: false, detail: 'type-2 transaction must contain exactly 12 RLP fields' };
    }
    const f = parsed.node;
    if (!Array.isArray(f[8])) return { ok: false, detail: 'type-2 RLP field types malformed' };
    if (f[8].length !== 0) return { ok: false, detail: 'VLM-001 forbids an access list' };
    const chainId = rlpUint(f[0], 'chainId');
    const nonce = rlpUint(f[1], 'nonce');
    const maxPriority = rlpUint(f[2], 'maxPriorityFeePerGas');
    const maxFee = rlpUint(f[3], 'maxFeePerGas');
    const gasLimit = rlpUint(f[4], 'gasLimit');
    const to = Buffer.from(f[5]);
    if (to.length !== 20) return { ok: false, detail: 'contract-creation transaction is forbidden' };
    const value = rlpUint(f[6], 'value');
    const data = Buffer.from(f[7]);
    const recovery = rlpUint(f[9], 'yParity');
    const r = rlpUint(f[10], 'r');
    const s = rlpUint(f[11], 's');
    if (recovery !== 0n && recovery !== 1n) return { ok: false, detail: 'EVM yParity must be 0 or 1' };
    if (r === 0n || s === 0n || s > EVM_HALF_N) return { ok: false, detail: 'EVM signature is not low-s canonical' };
    const unsigned = Buffer.concat([Buffer.from([2]), rlpEncode(f.slice(0, 9))]);
    const unsignedHash = Buffer.from(__keccak256(unsigned));
    const compact = Buffer.concat([
      Buffer.from(r.toString(16).padStart(64, '0'), 'hex'),
      Buffer.from(s.toString(16).padStart(64, '0'), 'hex'),
    ]);
    const signature = __secp256k1.Signature.fromCompact(compact).addRecoveryBit(Number(recovery));
    const pubkey = Buffer.from(signature.recoverPublicKey(unsignedHash).toBytes(false));
    const sender = '0x' + Buffer.from(__keccak256(pubkey.subarray(1))).subarray(12).toString('hex');
    return {
      ok: true,
      tx: {
        type: 2,
        chain_id: chainId.toString(),
        nonce: nonce.toString(),
        max_priority_fee_per_gas: maxPriority.toString(),
        max_fee_per_gas: maxFee.toString(),
        gas_limit: gasLimit.toString(),
        to: '0x' + to.toString('hex'),
        value: value.toString(),
        data: bytesHex(data),
        access_list_length: 0,
        unsigned_serialized: unsigned.toString('hex'),
        unsigned_hash: bytesHex(unsignedHash),
        signature: compact.toString('hex') + Number(recovery).toString(16).padStart(2, '0'),
        recovered_public_key: pubkey.toString('hex'),
        recovered_sender: sender,
        native_transaction_hash: bytesHex(__keccak256(raw)),
      },
    };
  } catch (err) {
    return { ok: false, detail: `raw transaction decode failed: ${String(err)}` };
  }
}

// -- strict word helpers ------------------------------------------------------
function lpDataBuffer(dataHex) {
  const hex = String(dataHex).toLowerCase().replace(/^0x/, '');
  if (!/^([0-9a-f]{2})*$/.test(hex)) throw new Error('calldata is not hex');
  return Buffer.from(hex, 'hex');
}

function lpWord(buf, i) {
  const start = 4 + i * 32;
  if (start + 32 > buf.length) throw new Error('calldata word out of range');
  return buf.subarray(start, start + 32);
}

function lpUintWordAt(buf, i) {
  return BigInt('0x' + lpWord(buf, i).toString('hex'));
}

function lpAddressWordAt(buf, i, label) {
  return evmAddressWord(lpWord(buf, i), label);
}

function lpSignedTickWordAt(buf, i, label) {
  const v = lpUintWordAt(buf, i);
  const signed = v >= 1n << 255n ? v - (1n << 256n) : v;
  if (signed < -8388608n || signed > 8388607n) throw new Error(`${label} is not a canonical int24`);
  // Two's-complement canonicality: re-encoding must reproduce the word.
  const reencoded = signed < 0n ? (1n << 256n) + signed : signed;
  if (reencoded !== v) throw new Error(`${label} word is not canonical`);
  return Number(signed);
}

function lpDecodeMint(element) {
  const buf = lpDataBuffer(element);
  if (buf.length !== 4 + 11 * 32 || buf.subarray(0, 4).toString('hex') !== LP_SELECTORS.mint) throw new Error('mint element malformed');
  return {
    token0: lpAddressWordAt(buf, 0, 'mint.token0'),
    token1: lpAddressWordAt(buf, 1, 'mint.token1'),
    fee: lpUintWordAt(buf, 2).toString(),
    tick_lower: lpSignedTickWordAt(buf, 3, 'mint.tickLower'),
    tick_upper: lpSignedTickWordAt(buf, 4, 'mint.tickUpper'),
    amount0_desired: lpUintWordAt(buf, 5).toString(),
    amount1_desired: lpUintWordAt(buf, 6).toString(),
    amount0_min: lpUintWordAt(buf, 7).toString(),
    amount1_min: lpUintWordAt(buf, 8).toString(),
    recipient: lpAddressWordAt(buf, 9, 'mint.recipient'),
    deadline: lpUintWordAt(buf, 10).toString(),
  };
}

function lpDecodeCollect(element) {
  const buf = lpDataBuffer(element);
  if (buf.length !== 4 + 4 * 32 || buf.subarray(0, 4).toString('hex') !== LP_SELECTORS.collect) throw new Error('collect element malformed');
  return {
    token_id: lpUintWordAt(buf, 0).toString(),
    recipient: lpAddressWordAt(buf, 1, 'collect.recipient'),
    amount0_max: lpUintWordAt(buf, 2).toString(),
    amount1_max: lpUintWordAt(buf, 3).toString(),
  };
}

function lpDecodeDecrease(element) {
  const buf = lpDataBuffer(element);
  if (buf.length !== 4 + 5 * 32 || buf.subarray(0, 4).toString('hex') !== LP_SELECTORS.decreaseLiquidity) throw new Error('decreaseLiquidity element malformed');
  return {
    token_id: lpUintWordAt(buf, 0).toString(),
    liquidity: lpUintWordAt(buf, 1).toString(),
    amount0_min: lpUintWordAt(buf, 2).toString(),
    amount1_min: lpUintWordAt(buf, 3).toString(),
    deadline: lpUintWordAt(buf, 4).toString(),
  };
}

// Strict canonical bytes[] multicall decode (the exact layout ethers emits).
function lpDecodeMulticallElements(dataHex) {
  try {
    const buf = lpDataBuffer(dataHex);
    if (buf.subarray(0, 4).toString('hex') !== LP_SELECTORS.multicall) return null;
    const body = buf.subarray(4);
    if (body.length < 64) return null;
    const headOffset = BigInt('0x' + body.subarray(0, 32).toString('hex'));
    if (headOffset !== 32n) return null;
    const count = Number(BigInt('0x' + body.subarray(32, 64).toString('hex')));
    if (!Number.isSafeInteger(count) || count < 0 || count > 16) return null;
    const arrayBase = 32; // offsets are relative to the start of the array data
    const offsets = [];
    for (let i = 0; i < count; i++) {
      offsets.push(Number(BigInt('0x' + body.subarray(64 + i * 32, 96 + i * 32).toString('hex'))));
    }
    const elements = [];
    let expectedOffset = 32 * count;
    for (let i = 0; i < count; i++) {
      if (offsets[i] !== expectedOffset) return null; // canonical tight packing only
      const lenPos = arrayBase + 32 + offsets[i];
      const len = Number(BigInt('0x' + body.subarray(lenPos, lenPos + 32).toString('hex')));
      const padded = Math.ceil(len / 32) * 32;
      const payload = body.subarray(lenPos + 32, lenPos + 32 + len);
      const padding = body.subarray(lenPos + 32 + len, lenPos + 32 + padded);
      if (payload.length !== len || padding.some((b) => b !== 0)) return null;
      elements.push('0x' + payload.toString('hex'));
      expectedOffset = offsets[i] + 32 + padded;
    }
    const total = arrayBase + 32 + expectedOffset;
    if (body.length !== total) return null;
    return elements;
  } catch {
    return null;
  }
}

function decodeLpCalldataStandalone(kind, data) {
  const selector = String(data).slice(2, 10).toLowerCase();
  try {
    switch (kind) {
      case 'open_tx1':
      case 'approval_reset': {
        if (selector !== LP_SELECTORS.approve) return { ok: false, detail: `calldata is not approve (0x${selector})` };
        const buf = lpDataBuffer(data);
        if (buf.length !== 4 + 2 * 32) return { ok: false, detail: 'LP calldata decode failed: Error: approve calldata malformed' };
        return { ok: true, call: { action: 'approve', spender: lpChecksumAddress(lpAddressWordAt(buf, 0, 'approve.spender')), amount: lpUintWordAt(buf, 1).toString() } };
      }
      case 'open_tx2': {
        if (selector !== LP_SELECTORS.multicall) return { ok: false, detail: `calldata is not multicall (0x${selector})` };
        const elements = lpDecodeMulticallElements(data);
        if (!elements) return { ok: false, detail: 'multicall decode failed' };
        if (elements.length !== 2) return { ok: false, detail: `open multicall must have exactly [mint, refundETH], got ${elements.length} elements` };
        if (elements[0].slice(2, 10) !== LP_SELECTORS.mint) return { ok: false, detail: 'open multicall element 0 is not mint' };
        if (elements[1] !== `0x${LP_SELECTORS.refundETH}`) return { ok: false, detail: 'open multicall element 1 is not a bare refundETH' };
        const mint = lpDecodeMint(elements[0]);
        return { ok: true, call: { action: 'open_mint', mint: { ...mint, token0: lpChecksumAddress(mint.token0), token1: lpChecksumAddress(mint.token1), recipient: lpChecksumAddress(mint.recipient) }, multicall_length: 2 } };
      }
      case 'collect': {
        if (selector !== LP_SELECTORS.collect) return { ok: false, detail: `calldata is not collect (0x${selector})` };
        const c = lpDecodeCollect(data);
        return { ok: true, call: { action: 'collect', collect: { ...c, recipient: lpChecksumAddress(c.recipient) } } };
      }
      case 'close': {
        if (selector !== LP_SELECTORS.multicall) return { ok: false, detail: `calldata is not multicall (0x${selector})` };
        const elements = lpDecodeMulticallElements(data);
        if (!elements) return { ok: false, detail: 'multicall decode failed' };
        if (elements.length !== 2 && elements.length !== 3) {
          return { ok: false, detail: `close multicall must be [decreaseLiquidity, collect(, burn)], got ${elements.length} elements` };
        }
        if (elements[0].slice(2, 10) !== LP_SELECTORS.decreaseLiquidity) return { ok: false, detail: 'close multicall element 0 is not decreaseLiquidity' };
        if (elements[1].slice(2, 10) !== LP_SELECTORS.collect) return { ok: false, detail: 'close multicall element 1 is not collect' };
        let burnTokenId = null;
        if (elements.length === 3) {
          if (elements[2].slice(2, 10) !== LP_SELECTORS.burn) return { ok: false, detail: 'close multicall element 2 is not burn' };
          const burnBuf = lpDataBuffer(elements[2]);
          if (burnBuf.length !== 36) return { ok: false, detail: 'LP calldata decode failed: Error: burn element malformed' };
          burnTokenId = lpUintWordAt(burnBuf, 0).toString();
        }
        const dec = lpDecodeDecrease(elements[0]);
        const col = lpDecodeCollect(elements[1]);
        return {
          ok: true,
          call: {
            action: 'close',
            decrease: dec,
            collect: { ...col, recipient: lpChecksumAddress(col.recipient) },
            burn_token_id: burnTokenId,
            multicall_length: elements.length,
          },
        };
      }
      default:
        return { ok: false, detail: `unknown LP action kind ${String(kind)}` };
    }
  } catch (err) {
    return { ok: false, detail: `LP calldata decode failed: ${String(err)}` };
  }
}

// -- adversarial artifact verification (byte-behavior port of lpArtifact.ts) --
function verifyLpOpenArtifactsStandalone(a) {
  const failed = (detail) => ({ ok: false, detail });
  let recomputed;
  try {
    recomputed = lpDeriveFullRangeOpenAmounts({
      sqrtPriceX96: BigInt(a.derivation.sqrt_price_x96),
      maxWethInWei: BigInt(a.maxWethInWei),
      maxSupraInWei: BigInt(a.maxSupraInWei),
      minOutBps: a.minOutBps,
    });
  } catch (err) {
    return failed(`derivation recompute failed: ${String(err)}`);
  }
  for (const key of ['liquidity', 'amount0_desired', 'amount1_desired', 'amount0_min', 'amount1_min']) {
    if (recomputed[key] !== a.derivation[key]) return failed(`pinned derivation is not self-consistent at ${key}`);
  }
  const d1 = decodeLpTransactionStandalone(a.tx1Hex);
  if (!d1.ok) return failed(`tx1: ${d1.detail}`);
  const d2 = decodeLpTransactionStandalone(a.tx2Hex);
  if (!d2.ok) return failed(`tx2: ${d2.detail}`);
  const tx1 = d1.tx;
  const tx2 = d2.tx;
  if (!addressEqEvm(tx1.recovered_sender, a.executionAddress) || !addressEqEvm(tx2.recovered_sender, a.executionAddress)) {
    return failed('sequence sender differs from the COSMO Execution Wallet');
  }
  if (tx1.chain_id !== a.chainId || tx2.chain_id !== a.chainId) return failed('sequence chainId differs from venue');
  if (tx1.nonce !== a.pendingNonce) return failed('tx1 nonce differs from fresh pending nonce');
  if (BigInt(tx2.nonce) !== BigInt(tx1.nonce) + 1n) return failed('tx2 nonce is not tx1 nonce + 1 (sequence binding)');
  if (!addressEqEvm(tx1.to, a.supraToken)) return failed('tx1 to differs from pinned SUPRA token');
  if (tx1.value !== '0') return failed('tx1 must carry no value');
  const c1 = decodeLpCalldataStandalone('open_tx1', tx1.data);
  if (!c1.ok) return failed(`tx1 calldata: ${c1.detail}`);
  if (c1.call.action !== 'approve') return failed('tx1 calldata is not approve');
  if (!addressEqEvm(c1.call.spender, a.nfpm)) return failed('tx1 approve spender differs from pinned NFPM');
  if (c1.call.amount !== a.derivation.amount1_desired) return failed('tx1 approve amount differs from derived SUPRA desired (exact-approval rule)');
  if (!addressEqEvm(tx2.to, a.nfpm)) return failed('tx2 to differs from pinned NFPM');
  if (tx2.value !== a.derivation.amount0_desired) return failed('tx2 value differs from derived WETH desired');
  const c2 = decodeLpCalldataStandalone('open_tx2', tx2.data);
  if (!c2.ok) return failed(`tx2 calldata: ${c2.detail}`);
  if (c2.call.action !== 'open_mint') return failed('tx2 calldata is not the open multicall');
  const mint = c2.call.mint;
  if (!addressEqEvm(mint.token0, a.wethToken) || !addressEqEvm(mint.token1, a.supraToken)) return failed('mint token pair differs from venue');
  if (mint.fee !== String(a.poolFee)) return failed('mint fee differs from venue');
  if (mint.tick_lower !== LP_FULL_RANGE_TICK_LOWER || mint.tick_upper !== LP_FULL_RANGE_TICK_UPPER) return failed('mint ticks are not the full range');
  if (!addressEqEvm(mint.recipient, a.sponsor)) return failed('mint recipient differs from the sponsor wallet');
  if (mint.amount0_desired !== a.derivation.amount0_desired || mint.amount1_desired !== a.derivation.amount1_desired) {
    return failed('mint desired amounts differ from the pinned derivation');
  }
  if (mint.amount0_min !== a.derivation.amount0_min || mint.amount1_min !== a.derivation.amount1_min) {
    return failed('mint minimum amounts differ from the pinned derivation');
  }
  if (BigInt(a.derivation.amount0_desired) > BigInt(a.maxWethInWei) || BigInt(a.derivation.amount1_desired) > BigInt(a.maxSupraInWei)) {
    return failed('derived desired amounts exceed the pinned caps');
  }
  if (mint.deadline !== a.deadline) return failed('mint deadline differs from preflight');
  if (BigInt(mint.deadline) <= BigInt(a.blockTimestamp)) return failed('mint deadline is not after the preflight block');
  if (BigInt(mint.deadline) - BigInt(a.blockTimestamp) > BigInt(a.transactionDeadlineSeconds)) return failed('mint deadline exceeds mandated duration');
  if (BigInt(mint.deadline) > BigInt(a.mandateExpiresAtMs) / 1000n) return failed('mint deadline exceeds mandate expiry');
  if (tx1.max_fee_per_gas !== tx2.max_fee_per_gas || tx1.max_priority_fee_per_gas !== tx2.max_priority_fee_per_gas) {
    return failed('sequence fee fields are not uniform');
  }
  if (BigInt(tx1.max_priority_fee_per_gas) > BigInt(tx1.max_fee_per_gas)) return failed('maxPriorityFeePerGas exceeds maxFeePerGas');
  if (BigInt(tx1.max_fee_per_gas) > BigInt(a.maxFeePerGasCapWei)) return failed('maxFeePerGas exceeds the pinned cap');
  const gasSum = BigInt(tx1.gas_limit) + BigInt(tx2.gas_limit);
  if (gasSum > BigInt(a.gasUnitsCap)) return failed('sequence gas limits exceed the aggregate units cap');
  if (gasSum * BigInt(tx1.max_fee_per_gas) > BigInt(a.maxGasCostWeiAbs)) return failed('sequence worst-case gas exceeds the absolute ceiling');
  return { ok: true, tx1, tx2, mint };
}

function verifyLpSingleArtifactStandalone(a) {
  const failed = (detail) => ({ ok: false, detail });
  const d = decodeLpTransactionStandalone(a.txHex);
  if (!d.ok) return failed(d.detail);
  const tx = d.tx;
  if (!addressEqEvm(tx.recovered_sender, a.executionAddress)) return failed('sender differs from the COSMO Execution Wallet');
  if (tx.chain_id !== a.chainId) return failed('chainId differs from venue');
  if (tx.nonce !== a.pendingNonce) return failed('nonce differs from fresh pending nonce');
  if (tx.value !== '0') return failed(`${a.kind} transaction must carry no value`);
  if (BigInt(tx.max_priority_fee_per_gas) > BigInt(tx.max_fee_per_gas)) return failed('maxPriorityFeePerGas exceeds maxFeePerGas');
  if (BigInt(tx.max_fee_per_gas) > BigInt(a.maxFeePerGasCapWei)) return failed('maxFeePerGas exceeds the pinned cap');
  if (BigInt(tx.gas_limit) > BigInt(a.gasUnitsCap)) return failed('gas limit exceeds the units cap');
  if (BigInt(tx.gas_limit) * BigInt(tx.max_fee_per_gas) > BigInt(a.maxGasCostWeiAbs)) return failed('worst-case gas exceeds the absolute ceiling');
  const call = decodeLpCalldataStandalone(a.kind, tx.data);
  if (!call.ok) return failed(call.detail);
  switch (a.kind) {
    case 'collect': {
      if (!addressEqEvm(tx.to, a.nfpm)) return failed('collect to differs from pinned NFPM');
      if (call.call.action !== 'collect') return failed('calldata is not collect');
      const c = call.call.collect;
      if (c.token_id !== a.tokenId) return failed('collect tokenId differs from the pinned token');
      if (!addressEqEvm(c.recipient, a.sponsor)) return failed('collect recipient differs from the sponsor wallet');
      if (c.amount0_max !== LP_MAX_UINT128 || c.amount1_max !== LP_MAX_UINT128) {
        return failed('collect amounts must be uint128.max (full fee collection)');
      }
      break;
    }
    case 'close': {
      if (!addressEqEvm(tx.to, a.nfpm)) return failed('close to differs from pinned NFPM');
      if (call.call.action !== 'close') return failed('calldata is not the close multicall');
      const c = call.call;
      if (c.decrease.token_id !== a.tokenId || c.collect.token_id !== a.tokenId) return failed('close tokenId differs from the pinned token');
      if (c.decrease.liquidity !== a.fullLiquidity) return failed('close liquidity is not 100% of the preflight position');
      if (c.decrease.amount0_min !== a.closeAmount0Min || c.decrease.amount1_min !== a.closeAmount1Min) {
        return failed('close minimum amounts differ from the preflight derivation');
      }
      if (!addressEqEvm(c.collect.recipient, a.sponsor)) return failed('close collect recipient differs from the sponsor wallet');
      if (c.collect.amount0_max !== LP_MAX_UINT128 || c.collect.amount1_max !== LP_MAX_UINT128) {
        return failed('close collect amounts must be uint128.max');
      }
      if (c.decrease.deadline !== a.deadline) return failed('close deadline differs from preflight');
      if (a.blockTimestamp === undefined || a.transactionDeadlineSeconds === undefined || a.mandateExpiresAtMs === undefined) {
        return failed('close deadline bounds are missing');
      }
      if (BigInt(c.decrease.deadline) <= BigInt(a.blockTimestamp)) return failed('close deadline is not after the preflight block');
      if (BigInt(c.decrease.deadline) - BigInt(a.blockTimestamp) > BigInt(a.transactionDeadlineSeconds)) return failed('close deadline exceeds mandated duration');
      if (BigInt(c.decrease.deadline) > BigInt(a.mandateExpiresAtMs) / 1000n) return failed('close deadline exceeds mandate expiry');
      if (c.burn_token_id !== null) {
        if (!a.burnAllowed) return failed('burn present but not allowed by the mandate');
        if (c.burn_token_id !== a.tokenId) return failed('burn tokenId differs from the pinned token');
      }
      break;
    }
    case 'approval_reset': {
      if (!addressEqEvm(tx.to, a.supraToken)) return failed('reset to differs from pinned SUPRA token');
      if (call.call.action !== 'approve') return failed('calldata is not approve');
      if (!addressEqEvm(call.call.spender, a.nfpm)) return failed('reset spender differs from pinned NFPM');
      if (call.call.amount !== '0') return failed('reset approve amount must be zero');
      break;
    }
    default:
      return failed(`unknown LP action kind ${String(a.kind)}`);
  }
  return { ok: true, tx, call: call.call };
}

// -- receipt log parsing (exactly-one discipline; strings match the TS side) --
const LP_ZERO_TOPIC = `0x${'0'.repeat(64)}`;

function lpTopicAddress(topic, label) {
  if (!/^0x[0-9a-fA-F]{64}$/.test(String(topic ?? ''))) throw new Error(`${label} topic malformed`);
  return lpChecksumAddress('0x' + String(topic).slice(-40));
}

function lpTopicUint(topic, label) {
  if (!/^0x[0-9a-fA-F]{64}$/.test(String(topic ?? ''))) throw new Error(`${label} topic malformed`);
  return BigInt(topic);
}

function lpDataWords(data, expected, label) {
  const hex = String(data ?? '').toLowerCase();
  if (!/^0x([0-9a-f]{64})*$/.test(hex) || (hex.length - 2) / 64 !== expected) {
    throw new Error(`${label} data must be exactly ${expected} words`);
  }
  const words = [];
  for (let i = 0; i < expected; i++) words.push(BigInt('0x' + hex.slice(2 + i * 64, 2 + (i + 1) * 64)));
  return words;
}

function lpLogsFrom(receipt) {
  const raw = receipt?.logs;
  if (!Array.isArray(raw)) return [];
  return raw.map((log) => ({
    address: String(log.address ?? ''),
    topics: Array.isArray(log.topics) ? log.topics.map((t) => String(t)) : [],
    data: String(log.data ?? '0x'),
  }));
}

function lpMatching(logs, contract, topic0) {
  return logs.filter((log) => addressEqEvm(log.address, contract) && String(log.topics[0] ?? '').toLowerCase() === topic0);
}

function lpFindMintTransfer(logs, nfpm, recipient) {
  try {
    const matches = lpMatching(logs, nfpm, LP_TOPICS.transfer).filter(
      (log) => String(log.topics[1] ?? '').toLowerCase() === LP_ZERO_TOPIC && addressEqEvm(lpTopicAddress(log.topics[2], 'Transfer.to'), recipient),
    );
    if (matches.length !== 1) return { ok: false, detail: `expected exactly one NFPM mint Transfer to the sponsor, got ${matches.length}` };
    return { ok: true, value: { token_id: lpTopicUint(matches[0].topics[3], 'Transfer.tokenId').toString() } };
  } catch (err) {
    return { ok: false, detail: String(err) };
  }
}

function lpFindBurnTransfer(logs, nfpm, owner, tokenId) {
  try {
    const matches = lpMatching(logs, nfpm, LP_TOPICS.transfer).filter(
      (log) =>
        addressEqEvm(lpTopicAddress(log.topics[1], 'Transfer.from'), owner) &&
        String(log.topics[2] ?? '').toLowerCase() === LP_ZERO_TOPIC &&
        lpTopicUint(log.topics[3], 'Transfer.tokenId').toString() === tokenId,
    );
    if (matches.length !== 1) return { ok: false, detail: `expected exactly one NFPM burn Transfer, got ${matches.length}` };
    return { ok: true, value: true };
  } catch (err) {
    return { ok: false, detail: String(err) };
  }
}

function lpFindLiquidityEvent(logs, nfpm, topic0, label, tokenId) {
  try {
    const matches = lpMatching(logs, nfpm, topic0).filter(
      (log) => tokenId === undefined || lpTopicUint(log.topics[1], `${label}.tokenId`).toString() === tokenId,
    );
    if (matches.length !== 1) return { ok: false, detail: `expected exactly one ${label} event, got ${matches.length}` };
    const words = lpDataWords(matches[0].data, 3, label);
    return {
      ok: true,
      value: {
        token_id: lpTopicUint(matches[0].topics[1], `${label}.tokenId`).toString(),
        liquidity: words[0].toString(),
        amount0: words[1].toString(),
        amount1: words[2].toString(),
      },
    };
  } catch (err) {
    return { ok: false, detail: String(err) };
  }
}

function lpFindCollectEvent(logs, nfpm, tokenId) {
  try {
    const matches = lpMatching(logs, nfpm, LP_TOPICS.collect).filter(
      (log) => lpTopicUint(log.topics[1], 'Collect.tokenId').toString() === tokenId,
    );
    if (matches.length !== 1) return { ok: false, detail: `expected exactly one Collect event, got ${matches.length}` };
    const words = lpDataWords(matches[0].data, 3, 'Collect');
    return {
      ok: true,
      value: {
        token_id: tokenId,
        recipient: lpChecksumAddress('0x' + words[0].toString(16).padStart(64, '0').slice(-40)),
        amount0: words[1].toString(),
        amount1: words[2].toString(),
      },
    };
  } catch (err) {
    return { ok: false, detail: String(err) };
  }
}

function lpFindApprovalZero(logs, token, owner, spender) {
  try {
    const matches = logs.filter(
      (log) =>
        addressEqEvm(log.address, token) &&
        String(log.topics[0] ?? '').toLowerCase() === LP_TOPICS.approval &&
        addressEqEvm(lpTopicAddress(log.topics[1], 'Approval.owner'), owner) &&
        addressEqEvm(lpTopicAddress(log.topics[2], 'Approval.spender'), spender),
    );
    if (matches.length !== 1) return { ok: false, detail: `expected exactly one Approval event, got ${matches.length}` };
    const words = lpDataWords(matches[0].data, 1, 'Approval');
    if (words[0] !== 0n) return { ok: false, detail: 'Approval value is not zero' };
    return { ok: true, value: true };
  } catch (err) {
    return { ok: false, detail: String(err) };
  }
}

// -- LP settlement re-derivation (port of domains/liquidityMandate/settlement.ts)
export const LP_SETTLEMENT_FINAL_SCHEMA = 'cosmo.liquidity-mandate-001.settlement-final.v1';

function lpActionOfKind(kind) {
  switch (kind) {
    case LM_OPEN_KIND: return 'open';
    case LM_COLLECT_KIND: return 'collect';
    case LM_CLOSE_KIND: return 'close';
    case LM_RESET_KIND: return 'approval_reset';
    default: throw new Error(`unknown LP kind ${String(kind)}`);
  }
}

function deriveNormativeLpPreparedStandalone({ kind, mandate, artifactHex, preflight, tx1Raw }) {
  const action = lpActionOfKind(kind);
  const p = mandate.action.params;
  const venue = p.venue;
  if (preflight.action !== action) return { ok: false, detail: 'preflight action differs from the case kind' };
  if (preflight.liquidity_mandate_id !== p.liquidity_mandate_id) {
    return { ok: false, detail: 'preflight liquidity_mandate_id differs from the mandate' };
  }
  const executionAddress = String(mandate.execution_key_ref ?? '').split(':')[1] ?? '';
  if (!addressEqEvm(preflight.sender, executionAddress)) {
    return { ok: false, detail: 'preflight sender differs from the mandate execution key' };
  }
  if (action === 'open') {
    if (!tx1Raw) return { ok: false, detail: 'OPEN requires the tx1 evidence (evm-lp-open-tx1.json)' };
    const derivation = preflight.readings?.derivation;
    if (!derivation) return { ok: false, detail: 'OPEN preflight carries no derivation' };
    if (preflight.deadline === null || preflight.deadline === undefined) return { ok: false, detail: 'OPEN preflight carries no deadline' };
    const verdict = verifyLpOpenArtifactsStandalone({
      tx1Hex: tx1Raw,
      tx2Hex: artifactHex,
      executionAddress,
      sponsor: p.sponsor,
      nfpm: venue.position_manager.address,
      supraToken: venue.token_out.address,
      wethToken: venue.token_in.weth,
      poolFee: venue.pool.fee,
      chainId: venue.chain.chain_id,
      derivation,
      maxWethInWei: p.max_weth_in_wei,
      maxSupraInWei: p.max_supra_in_wei,
      minOutBps: p.min_out_bps,
      pendingNonce: preflight.pending_nonce,
      deadline: preflight.deadline,
      blockTimestamp: preflight.trust.block_timestamp,
      transactionDeadlineSeconds: p.transaction_deadline_seconds,
      mandateExpiresAtMs: mandate.expires_at,
      gasUnitsCap: p.gas_units_cap,
      maxFeePerGasCapWei: p.max_fee_per_gas_cap_wei,
      maxGasCostWeiAbs: p.max_gas_cost_wei,
    });
    if (!verdict.ok) return { ok: false, detail: verdict.detail };
    const openCall = decodeLpCalldataStandalone('open_tx2', verdict.tx2.data);
    if (!openCall.ok) return { ok: false, detail: openCall.detail };
    return {
      ok: true,
      prepared: {
        lp_action: 'open',
        tx_hash: verdict.tx2.native_transaction_hash,
        raw_transaction: artifactHex,
        decoded: verdict.tx2,
        call: openCall.call,
        tx1: { tx_hash: verdict.tx1.native_transaction_hash, raw_transaction: tx1Raw, decoded: verdict.tx1 },
        preflight,
      },
    };
  }
  if (tx1Raw) return { ok: false, detail: `${action} must not carry a tx1 evidence file` };
  const verdict = verifyLpSingleArtifactStandalone({
    kind: action,
    txHex: artifactHex,
    executionAddress,
    sponsor: p.sponsor,
    nfpm: venue.position_manager.address,
    supraToken: venue.token_out.address,
    chainId: venue.chain.chain_id,
    pendingNonce: preflight.pending_nonce,
    gasUnitsCap: p.gas_units_cap,
    maxFeePerGasCapWei: p.max_fee_per_gas_cap_wei,
    maxGasCostWeiAbs: p.max_gas_cost_wei,
    tokenId: action === 'approval_reset' ? undefined : p.token_id,
    fullLiquidity: preflight.readings?.position?.liquidity,
    closeAmount0Min: preflight.readings?.close_mins?.amount0_min,
    closeAmount1Min: preflight.readings?.close_mins?.amount1_min,
    deadline: preflight.deadline ?? undefined,
    blockTimestamp: preflight.trust.block_timestamp,
    transactionDeadlineSeconds: p.transaction_deadline_seconds,
    mandateExpiresAtMs: mandate.expires_at,
    burnAllowed: action === 'close' ? p.burn_allowed : undefined,
  });
  if (!verdict.ok) return { ok: false, detail: verdict.detail };
  return {
    ok: true,
    prepared: {
      lp_action: action,
      tx_hash: verdict.tx.native_transaction_hash,
      raw_transaction: artifactHex,
      decoded: verdict.tx,
      call: verdict.call,
      tx1: null,
      preflight,
    },
  };
}

function lpHexEq(a, b) {
  return String(a ?? '').toLowerCase() === String(b ?? '').toLowerCase();
}

function validateLpSettlementStandalone({ mandate, prepared, snapshot, postState }) {
  const p = mandate.action.params;
  const venue = p.venue;
  const reject = (detail) => ({ kind: 'reject', detail });
  if (!snapshot.receipt) return { kind: 'pending' };
  const receipt = snapshot.receipt;
  if (String(receipt.status ?? '').toLowerCase() !== '0x1') return reject('settled transaction reverted');
  const tx = snapshot.transaction;
  if (!tx) return reject('settlement snapshot carries no transaction');
  if (!lpHexEq(tx.hash, prepared.tx_hash)) return reject('settled transaction hash differs from the case artifact');
  if (!addressEqEvm(String(tx.from ?? ''), prepared.decoded.recovered_sender)) return reject('settled sender differs from the artifact');
  if (!addressEqEvm(String(tx.to ?? ''), prepared.decoded.to)) return reject('settled to differs from the artifact');
  if (BigInt(String(tx.value ?? '0x0')) !== BigInt(prepared.decoded.value)) return reject('settled value differs from the artifact');
  if (BigInt(String(tx.nonce ?? '0x0')) !== BigInt(prepared.decoded.nonce)) return reject('settled nonce differs from the artifact');
  if (!lpHexEq(tx.input, prepared.decoded.data)) return reject('settled calldata differs from the artifact');
  const block = snapshot.canonical_block;
  if (!block) return reject('receipt block is not canonically readable');
  if (!lpHexEq(block.hash, receipt.blockHash) || BigInt(String(block.number ?? '0x0')) !== BigInt(String(receipt.blockNumber ?? '0x0'))) {
    return reject('receipt block is not canonical at its height');
  }
  if (BigInt(snapshot.confirmations) < BigInt(p.min_confirmations)) return { kind: 'pending' };
  const gasUsed = BigInt(String(receipt.gasUsed ?? '0x0'));
  const effectiveGasPrice = BigInt(String(receipt.effectiveGasPrice ?? '0x0'));
  if (gasUsed * effectiveGasPrice > BigInt(p.max_gas_cost_wei)) return reject('actual gas cost exceeds the mandated ceiling');
  const post = postState;
  if (!post) return reject('post-action state evidence is missing');
  if (!lpHexEq(post.block?.hash, receipt.blockHash)) return reject('post-state block differs from the receipt block');
  if (!lpHexEq(post.canonical_recheck?.hash, receipt.blockHash)) return reject('receipt block drifted during post-state reads');

  const logs = lpLogsFrom(receipt);
  const nfpm = venue.position_manager.address;
  const executionAddress = String(mandate.execution_key_ref ?? '').split(':')[1] ?? '';
  let tokenId = null;
  let liquidity = null;
  let amount0 = null;
  let amount1 = null;
  let recipient = null;
  let burn = null;
  let tx1Hash = null;

  switch (prepared.lp_action) {
    case 'open': {
      const transfer = lpFindMintTransfer(logs, nfpm, p.sponsor);
      if (!transfer.ok) return reject(transfer.detail);
      tokenId = transfer.value.token_id;
      const inc = lpFindLiquidityEvent(logs, nfpm, LP_TOPICS.increase_liquidity, 'IncreaseLiquidity', tokenId);
      if (!inc.ok) return reject(inc.detail);
      const derivation = prepared.preflight.readings?.derivation;
      if (!derivation) return reject('OPEN prepared preflight lost its derivation');
      if (BigInt(inc.value.amount0) > BigInt(p.max_weth_in_wei) || BigInt(inc.value.amount1) > BigInt(p.max_supra_in_wei)) {
        return reject('settled amounts exceed the pinned caps');
      }
      if (BigInt(inc.value.amount0) < BigInt(derivation.amount0_min) || BigInt(inc.value.amount1) < BigInt(derivation.amount1_min)) {
        return reject('settled amounts are below the 50-bps minimums');
      }
      liquidity = inc.value.liquidity;
      amount0 = inc.value.amount0;
      amount1 = inc.value.amount1;
      recipient = p.sponsor;
      tx1Hash = prepared.tx1?.tx_hash ?? null;
      if (!tx1Hash) return reject('OPEN prepared carries no tx1 hash');
      if (post.owner_of === null || post.owner_of === undefined || !addressEqEvm(post.owner_of, p.sponsor)) return reject('post-state owner differs from the sponsor');
      if (post.position_liquidity !== liquidity) return reject('post-state position liquidity differs from the IncreaseLiquidity event');
      break;
    }
    case 'collect': {
      const collect = lpFindCollectEvent(logs, nfpm, p.token_id);
      if (!collect.ok) return reject(collect.detail);
      if (!addressEqEvm(collect.value.recipient, p.sponsor)) return reject('collect recipient differs from the sponsor wallet');
      tokenId = p.token_id;
      amount0 = collect.value.amount0;
      amount1 = collect.value.amount1;
      recipient = collect.value.recipient;
      if (post.owner_of === null || post.owner_of === undefined || !addressEqEvm(post.owner_of, p.sponsor)) return reject('post-state owner differs from the sponsor');
      break;
    }
    case 'close': {
      if (prepared.call.action !== 'close') return reject('close prepared call has the wrong shape');
      const dec = lpFindLiquidityEvent(logs, nfpm, LP_TOPICS.decrease_liquidity, 'DecreaseLiquidity', p.token_id);
      if (!dec.ok) return reject(dec.detail);
      if (dec.value.liquidity !== prepared.call.decrease.liquidity) {
        return reject('decreased liquidity differs from 100% of the preflight position');
      }
      const collect = lpFindCollectEvent(logs, nfpm, p.token_id);
      if (!collect.ok) return reject(collect.detail);
      if (!addressEqEvm(collect.value.recipient, p.sponsor)) return reject('close collect recipient differs from the sponsor wallet');
      burn = prepared.call.burn_token_id !== null;
      if (burn) {
        const burned = lpFindBurnTransfer(logs, nfpm, p.sponsor, p.token_id);
        if (!burned.ok) return reject(burned.detail);
        if ((post.owner_of ?? null) !== null || (post.position_liquidity ?? null) !== null) return reject('post-state still shows the burned position');
      } else {
        if (post.position_liquidity !== '0') return reject('post-state position liquidity is not zero after close');
      }
      tokenId = p.token_id;
      liquidity = dec.value.liquidity;
      amount0 = collect.value.amount0;
      amount1 = collect.value.amount1;
      recipient = collect.value.recipient;
      break;
    }
    case 'approval_reset': {
      const approval = lpFindApprovalZero(logs, venue.token_out.address, executionAddress, nfpm);
      if (!approval.ok) return reject(approval.detail);
      if (post.supra_allowance_to_nfpm !== '0' || post.weth_allowance_to_nfpm !== '0') return reject('post-state allowance is not zero');
      if (post.supra_balance !== '0') return reject('post-state SUPRA residue is not swept to the sponsor');
      if (post.weth_balance !== '0') return reject('post-state WETH residue is not swept to the sponsor');
      if (BigInt(post.eth_balance) > BigInt(p.gas_headroom_wei)) return reject('post-state ETH exceeds the pinned gas reserve');
      break;
    }
    default:
      return reject(`unknown LP action ${String(prepared.lp_action)}`);
  }

  return {
    kind: 'confirmed',
    settlementRef: {
      lp_action: prepared.lp_action,
      liquidity_mandate_id: p.liquidity_mandate_id,
      transaction_hash: prepared.tx_hash,
      tx1_hash: tx1Hash,
      block_number: BigInt(String(receipt.blockNumber ?? '0x0')).toString(),
      block_hash: String(receipt.blockHash ?? '').toLowerCase(),
      confirmations: snapshot.confirmations,
      gas_used: gasUsed.toString(),
      effective_gas_price: effectiveGasPrice.toString(),
      token_id: tokenId,
      liquidity,
      amount0,
      amount1,
      recipient,
      burn,
      post_supra_allowance: post.supra_allowance_to_nfpm,
      post_weth_allowance: post.weth_allowance_to_nfpm,
      post_supra_balance: post.supra_balance,
      post_weth_balance: post.weth_balance,
      post_eth_balance: post.eth_balance,
    },
  };
}

function verifyLpFinalSettlementStandalone({ mandate, evidence, prepared }) {
  const embedded = evidence?.prepared;
  if (!embedded || typeof embedded !== 'object') return { kind: 'reject', detail: 'final settlement evidence carries no prepared transaction' };
  if (String(embedded.raw_transaction ?? '').toLowerCase() !== prepared.raw_transaction.toLowerCase()) {
    return { kind: 'reject', detail: 'final settlement raw transaction differs from the case artifact' };
  }
  if (String(embedded.tx_hash ?? '').toLowerCase() !== prepared.tx_hash) {
    return { kind: 'reject', detail: 'final settlement transaction hash differs from the case artifact' };
  }
  if ((embedded.tx1 === null || embedded.tx1 === undefined) !== (prepared.tx1 === null)) {
    return { kind: 'reject', detail: 'final settlement tx1 presence differs from the case artifact' };
  }
  if (embedded.tx1 && prepared.tx1 && String(embedded.tx1.raw_transaction ?? '').toLowerCase() !== prepared.tx1.raw_transaction.toLowerCase()) {
    return { kind: 'reject', detail: 'final settlement tx1 differs from the case tx1 evidence' };
  }
  if (canonicalize(embedded.preflight) !== canonicalize(prepared.preflight)) {
    return { kind: 'reject', detail: 'final settlement preflight differs from the case preflight evidence' };
  }
  const verdict = validateLpSettlementStandalone({ mandate, prepared, snapshot: evidence.snapshot, postState: evidence.post_state });
  if (verdict.kind !== 'confirmed') return verdict;
  if (canonicalize(evidence.settlement_ref) !== canonicalize(verdict.settlementRef)) {
    return { kind: 'reject', detail: 'final settlement_ref differs from the independent re-derivation' };
  }
  return verdict;
}

// ===========================================================================
// ported from: src/executionCase/domains/liquidityMandate/index.ts — VERIFY
// FACETS ONLY (four kinds share one factory).
// ===========================================================================

const LP_PREFLIGHT_FILE = 'evm-lp-preflight.json';
const LP_TX1_FILE = 'evm-lp-open-tx1.json';
const LP_FINAL_FILE = 'lp-settlement-final.json';
const LP_POST_STATE_FILE = 'lp-post-state.json';
const LP_TOKEN_ID_FILE = 'lp-token-id.json';
const LP_GATHER_FILE = 'lp-gather.json';
const LP_VENUE_FILE = 'lp-venue.json';
const LP_LEDGER_FILE = 'lp-ledger.json';
const LP_SCAN_FILE = 'lp-approval-scan.json';

function makeLmDomainStandalone(kind) {
  const action = lpActionOfKind(kind);
  return {
    kind,

    deriveDomainBlock(view) {
      const mandate = view.mandate;
      const p = mandate ? mandate.action.params : null;
      const preflightRaw = view.readEvidence(LP_PREFLIGHT_FILE);
      const preflight = preflightRaw ? JSON.parse(preflightRaw) : null;
      const verifyRaw = view.readEvidence(ARTIFACT_VERIFY_FILE);
      const artifactVerify = verifyRaw ? JSON.parse(verifyRaw) : null;
      const finalRaw = view.readEvidence(LP_FINAL_FILE);
      const settlementRef = finalRaw ? JSON.parse(finalRaw).settlement_ref : null;
      const tokenRaw = view.readEvidence(LP_TOKEN_ID_FILE);
      const tokenFromFile = tokenRaw ? JSON.parse(tokenRaw).token_id ?? null : null;
      return {
        liquidity_mandate_id: p?.liquidity_mandate_id ?? null,
        lp_action: action,
        venue_id: p?.venue?.venue_id ?? null,
        chain_id: p?.venue?.chain?.chain_id ?? null,
        genesis_block_hash: p?.venue?.chain?.genesis_block_hash ?? null,
        pool: p?.venue?.pool?.address ?? null,
        position_manager: p?.venue?.position_manager?.address ?? null,
        token_weth: p?.venue?.token_in?.weth ?? null,
        token_supra: p?.venue?.token_out?.address ?? null,
        sponsor: p?.sponsor ?? null,
        execution_wallet: p?.execution_wallet ?? null,
        token_id: p?.token_id ?? tokenFromFile,
        tx1_hash: artifactVerify?.sequence_tx1?.tx_hash ?? null,
        transaction_hash: artifactVerify?.native_transaction_hash ?? null,
        preflight_block_number: preflight?.trust?.block_number ?? null,
        derivation: preflight?.readings?.derivation ?? null,
        close_mins: preflight?.readings?.close_mins ?? null,
        settlement_ref: settlementRef,
      };
    },

    requiredFiles(outcome, _mode) {
      const base = [...CORE_EVIDENCE_BASE];
      const policyStage = ['mandate.json', 'mandate.sig.json', 'policy-decision.json', LP_VENUE_FILE, LP_GATHER_FILE, LP_LEDGER_FILE,
        ...(action === 'collect' || action === 'close' ? [LP_SCAN_FILE] : [])];
      const executionStage = [ARTIFACT_FILE, ARTIFACT_VERIFY_FILE, LP_PREFLIGHT_FILE,
        ...(action === 'open' ? [LP_TX1_FILE] : [])];
      const settlementStage = ['arm-consumed.json', 'submit-result.json', 'settlement-observations.jsonl', LP_FINAL_FILE, LP_POST_STATE_FILE,
        ...(action === 'open' ? [LP_TOKEN_ID_FILE] : [])];
      switch (outcome) {
        case 'INVALID_INTENT':
          return { required: [...base, 'intake-decision.json'], forbidden: ['mandate.json', ARTIFACT_FILE, 'submit-result.json'] };
        case 'POLICY_REJECTED':
          return { required: [...base, ...policyStage], forbidden: [...executionStage, 'submit-result.json', 'settlement-observations.jsonl'] };
        case 'EXPIRED':
          return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: ['submit-result.json'] };
        case 'HALTED':
          return { required: base, forbidden: [] };
        case 'EXECUTION_FAILED':
          return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
        case 'SHADOW_COMPLETED':
          return {
            required: [...base, ...policyStage, ...executionStage],
            forbidden: ['arm-consumed.json', 'submit-result.json', 'settlement-observations.jsonl', LP_FINAL_FILE, LP_POST_STATE_FILE, LP_TOKEN_ID_FILE],
          };
        case 'EXECUTED':
          return { required: [...base, ...policyStage, ...executionStage, ...settlementStage], forbidden: [] };
        case 'NO_COUNTERPARTY':
          return { required: base, forbidden: [] };
      }
    },

    allowedOutcomes: ['SHADOW_COMPLETED', 'EXECUTED', 'INVALID_INTENT', 'POLICY_REJECTED', 'EXPIRED', 'HALTED', 'EXECUTION_FAILED'],

    async checkArtifact({ artifactHex, mandate, evidenceDir }) {
      if (!mandate) return { ok: false, detail: 'LP artifact requires mandate.json' };
      try {
        const preflight = JSON.parse(readFileSync(join(evidenceDir, LP_PREFLIGHT_FILE), 'utf8'));
        let tx1Raw = null;
        if (action === 'open') {
          tx1Raw = JSON.parse(readFileSync(join(evidenceDir, LP_TX1_FILE), 'utf8')).raw_transaction;
        }
        const normative = deriveNormativeLpPreparedStandalone({ kind, mandate, artifactHex, preflight, tx1Raw });
        if (!normative.ok) return { ok: false, detail: normative.detail };
        const stored = JSON.parse(readFileSync(join(evidenceDir, ARTIFACT_VERIFY_FILE), 'utf8'));
        if (stored.artifact_format !== 'eip1559') return { ok: false, detail: 'artifact-verify format is not eip1559' };
        if (stored.lp_action !== action) return { ok: false, detail: 'artifact-verify lp_action differs from the case kind' };
        if (String(stored.native_transaction_hash ?? '') !== normative.prepared.tx_hash) {
          return { ok: false, detail: 'artifact-verify transaction hash differs from raw transaction' };
        }
        const localVerify = stored.local_verify;
        if (localVerify?.ok !== true || !addressEqEvm(String(localVerify?.derivedAddressHex ?? ''), normative.prepared.decoded.recovered_sender)) {
          return { ok: false, detail: 'artifact-verify signer differs from recovered raw-transaction signer' };
        }
        if (action === 'open') {
          const seq = stored.sequence_tx1;
          if (!seq || String(seq.tx_hash ?? '') !== normative.prepared.tx1?.tx_hash ||
              String(seq.raw_transaction ?? '').toLowerCase() !== normative.prepared.tx1?.raw_transaction.toLowerCase()) {
            return { ok: false, detail: 'artifact-verify tx1 differs from the tx1 evidence' };
          }
        }
        return { ok: true };
      } catch (err) {
        return { ok: false, detail: `LP artifact evidence invalid: ${String(err)}` };
      }
    },

    checkOutcomeExtensions({ stmt, evidenceDir }) {
      // D0c (W5): for collect/close the approval-scan evidence must be the
      // chunked scan from the MANDATED start block — a scan starting late (or
      // a preflight scanning a different range) could hide a standing
      // ApprovalForAll (fraud vector 12). Both verifiers run this identically.
      if ((action === 'collect' || action === 'close') && (stmt.outcome === 'SHADOW_COMPLETED' || stmt.outcome === 'EXECUTED')) {
        try {
          const mandate = JSON.parse(readFileSync(join(evidenceDir, 'mandate.json'), 'utf8'));
          const p = mandate.action.params;
          const pinned = String(p.approval_scan_from_block ?? '');
          if (!/^[1-9][0-9]*$/.test(pinned)) return { ok: false, detail: 'mandate carries no pinned approval_scan_from_block' };
          const scan = JSON.parse(readFileSync(join(evidenceDir, LP_SCAN_FILE), 'utf8'));
          if (!scan || typeof scan !== 'object') return { ok: false, detail: 'approval scan evidence missing or malformed' };
          if (String(scan.from_block ?? '') !== pinned) {
            return { ok: false, detail: 'approval scan start block differs from the mandated pin' };
          }
          if (String(scan.chunk_size ?? '') !== '10000' || !Array.isArray(scan.logs)) {
            return { ok: false, detail: 'approval scan evidence is not the 10000-block chunked scan' };
          }
          if (BigInt(String(scan.from_block)) > BigInt(String(scan.to_block ?? '0'))) {
            return { ok: false, detail: 'approval scan range is empty (start beyond observation block)' };
          }
          const preflight = JSON.parse(readFileSync(join(evidenceDir, LP_PREFLIGHT_FILE), 'utf8'));
          const auth = preflight.readings.nft_auth;
          if (!auth || auth.scan_from_block !== pinned || auth.scan_to_block !== preflight.readings.block_number ||
              auth.scan_chunk_size !== '10000') {
            return { ok: false, detail: 'preflight approval scan does not cover the pinned start block through the preflight block' };
          }
        } catch (err) {
          return { ok: false, detail: `approval scan evidence invalid: ${String(err)}` };
        }
      }
      if (stmt.outcome === 'SHADOW_COMPLETED') {
        if (stmt.domain?.settlement_ref != null) return { ok: false, detail: 'LP shadow must not carry settlement evidence' };
        const verified = JSON.parse(readFileSync(join(evidenceDir, ARTIFACT_VERIFY_FILE), 'utf8'));
        if (verified.local_verify?.ok !== true) return { ok: false, detail: 'LP shadow requires local transaction verification' };
      }
      if (stmt.outcome === 'EXECUTED') {
        if (stmt.domain?.settlement_ref == null) return { ok: false, detail: 'LP EXECUTED requires settlement_ref' };
        try {
          const submit = JSON.parse(readFileSync(join(evidenceDir, 'submit-result.json'), 'utf8'));
          if (submit.ok !== true || submit.attempts !== 1) return { ok: false, detail: 'LP EXECUTED requires exactly one accepted submit attempt' };
          const mandate = JSON.parse(readFileSync(join(evidenceDir, 'mandate.json'), 'utf8'));
          const preflight = JSON.parse(readFileSync(join(evidenceDir, LP_PREFLIGHT_FILE), 'utf8'));
          let tx1Raw = null;
          if (action === 'open') {
            tx1Raw = JSON.parse(readFileSync(join(evidenceDir, LP_TX1_FILE), 'utf8')).raw_transaction;
          }
          const normative = deriveNormativeLpPreparedStandalone({
            kind,
            mandate,
            artifactHex: readFileSync(join(evidenceDir, ARTIFACT_FILE), 'utf8').trim(),
            preflight,
            tx1Raw,
          });
          if (!normative.ok) return { ok: false, detail: `LP settled artifact is not verifiable: ${normative.detail}` };
          const evidence = JSON.parse(readFileSync(join(evidenceDir, LP_FINAL_FILE), 'utf8'));
          const postRaw = JSON.parse(readFileSync(join(evidenceDir, LP_POST_STATE_FILE), 'utf8'));
          if (canonicalize(postRaw) !== canonicalize(evidence.post_state)) {
            return { ok: false, detail: 'lp-post-state.json differs from the settlement-final post_state' };
          }
          const verdict = verifyLpFinalSettlementStandalone({ mandate, evidence, prepared: normative.prepared });
          if (verdict.kind !== 'confirmed') {
            return { ok: false, detail: verdict.kind === 'reject' ? verdict.detail : 'final LP settlement is not confirmed' };
          }
          if (canonicalize(stmt.domain?.settlement_ref) !== canonicalize(verdict.settlementRef)) {
            return { ok: false, detail: 'receipt settlement_ref differs from final settlement evidence' };
          }
          const settledHash = String(verdict.settlementRef.transaction_hash ?? '').toLowerCase();
          if (String(stmt.domain?.transaction_hash ?? '').toLowerCase() !== settledHash) {
            return { ok: false, detail: 'receipt transaction_hash differs from the settled transaction hash' };
          }
          if (settledHash !== normative.prepared.tx_hash) {
            return { ok: false, detail: 'settled transaction hash differs from the verified artifact transaction hash' };
          }
          if (action === 'open') {
            const tokenFile = JSON.parse(readFileSync(join(evidenceDir, LP_TOKEN_ID_FILE), 'utf8'));
            if (String(tokenFile.token_id ?? '') !== String(verdict.settlementRef.token_id ?? '')) {
              return { ok: false, detail: 'lp-token-id.json differs from the settled tokenId' };
            }
          }
        } catch (err) {
          return { ok: false, detail: `LP final settlement evidence invalid: ${String(err)}` };
        }
      }
      return { ok: true };
    },
  };
}

const lmOpenDomain = makeLmDomainStandalone(LM_OPEN_KIND);
const lmCollectDomain = makeLmDomainStandalone(LM_COLLECT_KIND);
const lmCloseDomain = makeLmDomainStandalone(LM_CLOSE_KIND);
const lmResetDomain = makeLmDomainStandalone(LM_RESET_KIND);

