// ===========================================================================
// ported from: src/executionCase/legacy/v1/typesV1.ts (FROZEN v1 surface)
// ===========================================================================

export const MANDATE_SCHEMA_V1 = 'cosmo.execution-case.mandate.v1';
export const RECEIPT_SCHEMA_V1 = 'cosmo.execution-case.receipt.v1';

export const MANDATE_DOMAIN_V1 = 'COSMO-EXECUTION-CASE MANDATE v1';

export function mandateMessageV1(caseId, hash) {
  return Buffer.from(`${MANDATE_DOMAIN_V1}\ncase: ${caseId}\nhash: ${hash}`, 'utf8');
}

export function rfqIdFromMandateHashV1(hash) {
  if (!/^0x[0-9a-f]{64}$/.test(hash)) throw new Error(`malformed mandate hash: ${hash}`);
  return hash.slice(2, 34);
}

// ===========================================================================
// ported from: src/executionCase/legacy/v1/receiptV1.ts (FROZEN v1 derivation)
// ===========================================================================

export function loadEvidenceViewV1(cDir) {
  const manifest = JSON.parse(readFileSync(join(cDir, 'MANIFEST.json'), 'utf8'));
  const dir = evidenceDir(cDir);
  const readIf = (name) => (manifest.files[name] ? readFileSync(join(dir, name), 'utf8') : null);

  const mandateRaw = readIf('mandate.json');
  const intentRaw = readIf('intent.json');
  let intentParsed = null;
  try {
    intentParsed = intentRaw ? JSON.parse(intentRaw) : null;
  } catch {
    intentParsed = null;
  }
  const envVerifyRaw = readIf('envelope-verify.json');
  const settlementRaw = readIf('settlement-observations.jsonl');
  let settlementRef = null;
  if (settlementRaw) {
    const lines = settlementRaw.split('\n').filter(Boolean);
    for (const line of lines) {
      const obs = JSON.parse(line);
      if (obs.confirming && obs.settlement_ref) settlementRef = obs.settlement_ref;
    }
  }
  return {
    manifest,
    mandate: mandateRaw ? JSON.parse(mandateRaw) : null,
    intentParsed,
    envelopeHex: readIf('envelope.hex')?.trim() ?? null,
    envelopeVerify: envVerifyRaw ? JSON.parse(envVerifyRaw) : null,
    settlementRef,
  };
}

export function deriveReceiptStatementV1(view, ctx) {
  const m = view.mandate;
  return {
    schema: RECEIPT_SCHEMA_V1,
    case_id: ctx.case_id,
    outcome: ctx.outcome,
    outcome_detail: ctx.outcome_detail,
    mode: ctx.mode,
    principal_ref: m?.principal_ref ?? view.intentParsed?.principal_ref ?? null,
    agent_ref: m?.agent_ref ?? view.intentParsed?.agent_ref ?? null,
    execution_key_ref: m?.execution_key_ref ?? null,
    mandate_hash: m ? sha3Hex(canonicalize(m)) : null,
    policy_hash: view.manifest.policy_hash,
    execution_ref: view.envelopeHex ? sha3Hex(Buffer.from(view.envelopeHex, 'hex')) : null,
    settlement_ref: view.settlementRef,
    evidence_root: evidenceRoot(view.manifest),
    pair: m
      ? { base_chain: m.pair.base_chain, base_symbol: m.pair.base_symbol, quote_chain: m.pair.quote_chain, quote_symbol: m.pair.quote_symbol }
      : view.intentParsed?.pair ?? null,
    size_base: m?.size_base ?? view.intentParsed?.size_base ?? null,
    created_at: ctx.created_at,
    closed_at: ctx.closed_at,
    chain: view.envelopeVerify?.chain ?? null,
    context: { producer_commit: ctx.producer_commit, sdk_version: ctx.sdk_version },
  };
}

export function receiptSignedBytesV1(attestor, attestedAt, statement) {
  return Buffer.from(canonicalize({ envelope: { attestor, attested_at: attestedAt }, statement }), 'utf8');
}

export function requiredFilesV1(outcome, _mode) {
  const base = ['intent.json', 'policy.json', 'errors.json'];
  switch (outcome) {
    case 'INVALID_INTENT':
      return { required: [...base, 'intake-decision.json'], forbidden: ['mandate.json', 'envelope.hex', 'submit-result.json'] };
    case 'POLICY_REJECTED':
      return {
        required: [...base, 'mandate.json', 'mandate.sig.json', 'policy-decision.json', 'reference-price.json'],
        forbidden: ['envelope.hex', 'submit-result.json'],
      };
    case 'EXPIRED':
      return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
    case 'HALTED':
      return { required: [...base], forbidden: [] };
    case 'EXECUTION_FAILED':
      return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
    case 'SHADOW_COMPLETED':
      return {
        required: [
          ...base,
          'mandate.json',
          'mandate.sig.json',
          'policy-decision.json',
          'reference-price.json',
          'envelope.hex',
          'envelope-verify.json',
        ],
        forbidden: ['submit-result.json', 'settlement-observations.jsonl'],
      };
    case 'EXECUTED':
      return {
        required: [
          ...base,
          'mandate.json',
          'mandate.sig.json',
          'policy-decision.json',
          'reference-price.json',
          'envelope.hex',
          'envelope-verify.json',
          'arm-consumed.json',
          'submit-result.json',
          'settlement-observations.jsonl',
        ],
        forbidden: [],
      };
    case 'NO_COUNTERPARTY':
      return {
        required: [
          ...base,
          'mandate.json',
          'mandate.sig.json',
          'policy-decision.json',
          'reference-price.json',
          'envelope.hex',
          'envelope-verify.json',
          'arm-consumed.json',
          'submit-result.json',
          'settlement-observations.jsonl',
        ],
        forbidden: [],
      };
  }
}

// ===========================================================================
// ported from: src/executionCase/legacy/v1/verifyV1.ts (FROZEN v1 verifier)
// ===========================================================================

const T_BACK_SKEW_MS = 300_000;
const T_FWD_LIMIT_MS = 86_400_000;

export async function verifyCaseV1(cDir, opts) {
  const results = [];
  const fail = (criterion, detail) => {
    results.push({ criterion, ok: false, detail });
    return { rc: 1, results };
  };
  const pass = (criterion, detail) => results.push({ criterion, ok: true, detail });

  try {
    const receiptRaw = readFileSync(join(cDir, 'receipt.json'), 'utf8');
    const receipt = JSON.parse(receiptRaw);
    const topKeys = Object.keys(receipt).sort();
    if (JSON.stringify(topKeys) !== JSON.stringify(['envelope', 'statement'])) {
      return fail('S signature', `receipt top-level keys must be exactly [envelope, statement], got [${topKeys.join(',')}]`);
    }
    const envKeys = Object.keys(receipt.envelope).sort();
    if (JSON.stringify(envKeys) !== JSON.stringify(['attested_at', 'attestor', 'signature'])) {
      return fail('S signature', 'receipt envelope keys must be exactly [attestor, attested_at, signature]');
    }
    const stmt = receipt.statement;
    if (stmt.schema !== RECEIPT_SCHEMA_V1) return fail('S signature', `statement schema must be ${RECEIPT_SCHEMA_V1}`);

    // K
    if (!opts.trust.attestors[receipt.envelope.attestor]?.active) {
      return fail('K attestor pinned', `attestor ${receipt.envelope.attestor.slice(0, 16)}... has no active pin`);
    }
    pass('K attestor pinned');

    // S
    const signed = receiptSignedBytesV1(receipt.envelope.attestor, receipt.envelope.attested_at, stmt);
    if (!verifyBytes(receipt.envelope.attestor, signed, receipt.envelope.signature)) {
      return fail('S signature', 'receipt signature invalid over canonical(envelope minus signature, statement)');
    }
    pass('S signature');

    // T
    if (!(Number.isInteger(stmt.created_at) && Number.isInteger(stmt.closed_at) && stmt.created_at <= stmt.closed_at)) {
      return fail('T time bounds', 'created_at/closed_at not sane');
    }
    const dt = receipt.envelope.attested_at - stmt.closed_at;
    if (dt < -T_BACK_SKEW_MS || dt > T_FWD_LIMIT_MS) {
      return fail('T time bounds', `attested_at deviates ${dt}ms from closed_at (allowed [-${T_BACK_SKEW_MS}, ${T_FWD_LIMIT_MS}])`);
    }
    pass('T time bounds');

    // P
    const eDir = evidenceDir(cDir);
    const policyOnDisk = JSON.parse(readFileSync(join(eDir, 'policy.json'), 'utf8'));
    const policyHash = canonicalHash(policyOnDisk);
    if (policyHash !== stmt.policy_hash) {
      return fail('P policy pinned', `statement.policy_hash ${stmt.policy_hash} != hash of evidence policy copy ${policyHash}`);
    }
    if (!opts.trust.policies[policyHash]?.active) {
      return fail('P policy pinned', `policy hash ${policyHash} has no active pin`);
    }
    const manifest = JSON.parse(readFileSync(join(cDir, 'MANIFEST.json'), 'utf8'));
    if (manifest.policy_hash !== policyHash) {
      return fail('P policy pinned', 'manifest.policy_hash differs from evidence policy hash');
    }
    pass('P policy pinned');

    // M
    let mandate = null;
    if (manifest.files['mandate.json']) {
      mandate = JSON.parse(readFileSync(join(eDir, 'mandate.json'), 'utf8'));
      const sig = JSON.parse(readFileSync(join(eDir, 'mandate.sig.json'), 'utf8'));
      if (mandate.schema !== MANDATE_SCHEMA_V1) return fail('M mandate integrity', 'mandate schema mismatch');
      const mHash = canonicalHash(mandate);
      if (stmt.mandate_hash !== mHash) {
        return fail('M mandate integrity', `statement.mandate_hash != recomputed hash of mandate.json (${mHash})`);
      }
      if (!opts.trust.attestors[sig.attestor_pubkey]?.active) {
        return fail('M mandate integrity', 'mandate attestor key has no active pin');
      }
      if (!verifyBytes(sig.attestor_pubkey, mandateMessageV1(mandate.case_id, mHash), sig.signature)) {
        return fail('M mandate integrity', 'mandate signature invalid over recomputed hash');
      }
      if (mandate.policy_hash !== stmt.policy_hash) {
        return fail('M mandate integrity', 'mandate.policy_hash differs from statement.policy_hash');
      }
      if (mandate.case_id !== stmt.case_id) return fail('M mandate integrity', 'mandate.case_id differs from statement.case_id');
    } else if (stmt.mandate_hash !== null) {
      return fail('M mandate integrity', 'statement carries a mandate_hash but no mandate.json exists');
    }
    pass('M mandate integrity');

    // V
    const dirNames = readdirSync(eDir).sort();
    const manifestNames = Object.keys(manifest.files).sort();
    if (JSON.stringify(dirNames) !== JSON.stringify(manifestNames)) {
      return fail('V evidence integrity', `evidence set mismatch: dir [${dirNames.join(',')}] vs manifest [${manifestNames.join(',')}]`);
    }
    for (const name of manifestNames) {
      const st = lstatSync(join(eDir, name));
      if (st.isSymbolicLink() || !st.isFile()) return fail('V evidence integrity', `${name} is not a regular file`);
      const bytes = readFileSync(join(eDir, name));
      if (bytes.length !== manifest.files[name].bytes) return fail('V evidence integrity', `${name} byte length drift`);
      if (sha3Hex(bytes) !== manifest.files[name].sha3) return fail('V evidence integrity', `${name} sha3 drift`);
    }
    if (!manifest.files['errors.json']) return fail('V evidence integrity', 'errors.json missing (mandatory)');
    if (stmt.evidence_root !== canonicalHash(manifest)) {
      return fail('V evidence integrity', 'statement.evidence_root != sha3(canonical(manifest))');
    }
    pass('V evidence integrity');

    // J
    const scan = scanJournal(join(cDir, 'journal.jsonl'));
    if (!scan.ok) return fail('J journal chain', `chain broken at line ${scan.firstBad}: ${scan.error}`);
    if (scan.lines < 2) return fail('J journal chain', 'journal too short');
    const events = scan.entries.map((e) => e.event);
    if (events[0] !== 'case_opened') return fail('J journal chain', 'first journal event must be case_opened');
    if (events[events.length - 1] !== 'case_closed') return fail('J journal chain', 'last journal event must be case_closed');
    if (events.filter((e) => e === 'case_closed').length !== 1) return fail('J journal chain', 'case_closed must occur exactly once');
    if (scan.entries.some((e) => e.case_id !== stmt.case_id)) return fail('J journal chain', 'journal case_id drift');
    const closedEntry = scan.entries[scan.entries.length - 1];
    if (closedEntry.evidence_root !== stmt.evidence_root) {
      return fail('J journal chain', 'journal case_closed.evidence_root differs from statement.evidence_root');
    }
    if (closedEntry.outcome !== stmt.outcome) return fail('J journal chain', 'journal outcome differs from statement.outcome');
    pass('J journal chain');

    // E
    if (manifest.files['envelope.hex']) {
      const envelopeHex = readFileSync(join(eDir, 'envelope.hex'), 'utf8').trim();
      if (!stmt.chain) return fail('E envelope', 'envelope present but statement.chain is null');
      if (stmt.execution_ref !== sha3Hex(Buffer.from(envelopeHex, 'hex'))) {
        return fail('E envelope', 'statement.execution_ref != sha3 of envelope bytes');
      }
      const checker = opts.envelopeChecker ?? defaultEnvelopeChecker;
      const verdict = await checker(envelopeHex, stmt.chain.chain_id_hash_hex);
      if (!verdict.ok) return fail('E envelope', `SDK verifyEnvelope failed: ${verdict.reason}`);
      const envVerify = JSON.parse(readFileSync(join(eDir, 'envelope-verify.json'), 'utf8'));
      if (verdict.signerPubkeyHex && envVerify.signer_pubkey && verdict.signerPubkeyHex !== envVerify.signer_pubkey) {
        return fail('E envelope', 'decoded signer pubkey differs from envelope-verify.json');
      }
      if (mandate && stmt.mandate_hash && verdict.eventBcsHex) {
        const rfqId = rfqIdFromMandateHashV1(stmt.mandate_hash);
        if (!verdict.eventBcsHex.includes(rfqId)) {
          return fail('E envelope', 'rfq_id derived from mandate_hash not present in event bytes (mandate/envelope unlinked)');
        }
      }
    } else if (stmt.execution_ref !== null) {
      return fail('E envelope', 'statement carries execution_ref but no envelope.hex exists');
    }
    pass('E envelope');

    // D — derivation equality via THE frozen v1 builder
    const ctx = {
      case_id: stmt.case_id,
      outcome: stmt.outcome,
      outcome_detail: stmt.outcome_detail,
      mode: stmt.mode,
      created_at: stmt.created_at,
      closed_at: stmt.closed_at,
      producer_commit: stmt.context.producer_commit,
      sdk_version: stmt.context.sdk_version,
    };
    const rederived = deriveReceiptStatementV1(loadEvidenceViewV1(cDir), ctx);
    if (canonicalize(rederived) !== canonicalize(stmt)) {
      return fail('D derivation equality', 'statement differs from deriveReceiptStatement() over the same evidence');
    }
    pass('D derivation equality');

    // O — outcome consistency
    const contract = requiredFilesV1(stmt.outcome, stmt.mode);
    for (const r of contract.required) {
      if (!manifest.files[r]) return fail('O outcome consistency', `required evidence ${r} missing for outcome ${stmt.outcome}`);
    }
    for (const f of contract.forbidden) {
      if (manifest.files[f]) return fail('O outcome consistency', `forbidden evidence ${f} present for outcome ${stmt.outcome}`);
    }
    if (mandate && stmt.mode !== mandate.mode) return fail('O outcome consistency', 'statement.mode differs from mandate.mode');
    if (stmt.mode === 'shadow' && (stmt.outcome === 'EXECUTED' || stmt.outcome === 'NO_COUNTERPARTY')) {
      return fail('O outcome consistency', `mode shadow can never close as ${stmt.outcome}`);
    }
    if (stmt.outcome === 'SHADOW_COMPLETED') {
      if (stmt.mode !== 'shadow') return fail('O outcome consistency', 'SHADOW_COMPLETED requires mode shadow');
      if (stmt.settlement_ref !== null) return fail('O outcome consistency', 'SHADOW_COMPLETED must carry settlement_ref null');
      const envVerify = JSON.parse(readFileSync(join(eDir, 'envelope-verify.json'), 'utf8'));
      if (envVerify.local_verify?.ok !== true) return fail('O outcome consistency', 'SHADOW_COMPLETED requires local_verify.ok');
    }
    if (stmt.outcome === 'EXECUTED') {
      if (stmt.mode !== 'micro_live') return fail('O outcome consistency', 'EXECUTED requires mode micro_live');
      if (stmt.settlement_ref === null) return fail('O outcome consistency', 'EXECUTED requires a settlement_ref');
      const submit = JSON.parse(readFileSync(join(eDir, 'submit-result.json'), 'utf8'));
      if (submit.ok !== true) return fail('O outcome consistency', 'EXECUTED requires submit-result.ok');
    }
    if (stmt.outcome === 'INVALID_INTENT') {
      if (stmt.mandate_hash !== null) return fail('O outcome consistency', 'INVALID_INTENT must not carry a mandate_hash');
      const intake = JSON.parse(readFileSync(join(eDir, 'intake-decision.json'), 'utf8'));
      if (intake.verdict !== 'reject') return fail('O outcome consistency', 'INVALID_INTENT requires a rejecting intake decision');
      if (intake.criterion !== stmt.outcome_detail.criterion) {
        return fail('O outcome consistency', 'intake criterion differs from outcome_detail.criterion');
      }
    }
    if (stmt.outcome === 'POLICY_REJECTED') {
      const decision = JSON.parse(readFileSync(join(eDir, 'policy-decision.json'), 'utf8'));
      if (decision.verdict !== 'reject') return fail('O outcome consistency', 'POLICY_REJECTED requires a rejecting policy decision');
      if (decision.criterion !== stmt.outcome_detail.criterion) {
        return fail('O outcome consistency', 'policy criterion differs from outcome_detail.criterion');
      }
    }
    if (stmt.outcome === 'NO_COUNTERPARTY') {
      const obsRaw = readFileSync(join(eDir, 'settlement-observations.jsonl'), 'utf8');
      const lines = obsRaw
        .split('\n')
        .filter(Boolean)
        .map((l) => JSON.parse(l));
      if (lines.length === 0) return fail('O outcome consistency', 'NO_COUNTERPARTY requires observation snapshots');
      if (lines.some((o) => o.confirming === true)) {
        return fail('O outcome consistency', 'NO_COUNTERPARTY but a confirming fill observation exists');
      }
      const lastObs = lines[lines.length - 1];
      if (lastObs.deadline_reached !== true || lastObs.fill !== false) {
        return fail('O outcome consistency', 'NO_COUNTERPARTY requires a final deadline_reached observation without fill');
      }
      if (stmt.settlement_ref !== null) return fail('O outcome consistency', 'NO_COUNTERPARTY must carry settlement_ref null');
    }
    pass('O outcome consistency');

    return { rc: 0, results };
  } catch (err) {
    return { rc: 2, results, error: String(err) };
  }
}

// ===========================================================================
// ported from: src/executionCase/verifier/verifyV2.ts
// ===========================================================================

export async function verifyCaseV2(cDir, opts) {
  const domains = opts.domains ?? DOMAINS;
  const results = [];
  const fail = (criterion, detail) => {
    results.push({ criterion, ok: false, detail });
    return { rc: 1, results };
  };
  const pass = (criterion, detail) => results.push({ criterion, ok: true, detail });

  try {
    // --- Load + closed-key-set checks on the receipt itself ---
    const receiptRaw = readFileSync(join(cDir, 'receipt.json'), 'utf8');
    const receipt = JSON.parse(receiptRaw);
    const topKeys = Object.keys(receipt).sort();
    if (JSON.stringify(topKeys) !== JSON.stringify(['envelope', 'statement'])) {
      return fail('S signature', `receipt top-level keys must be exactly [envelope, statement], got [${topKeys.join(',')}]`);
    }
    const envKeys = Object.keys(receipt.envelope).sort();
    if (JSON.stringify(envKeys) !== JSON.stringify(['attested_at', 'attestor', 'signature'])) {
      return fail('S signature', 'receipt envelope keys must be exactly [attestor, attested_at, signature]');
    }
    const stmt = receipt.statement;
    if (stmt.schema !== RECEIPT_SCHEMA) return fail('S signature', `statement schema must be ${RECEIPT_SCHEMA}`);

    // K
    if (!opts.trust.attestors[receipt.envelope.attestor]?.active) {
      return fail('K attestor pinned', `attestor ${receipt.envelope.attestor.slice(0, 16)}... has no active pin`);
    }
    pass('K attestor pinned');

    // S
    const signed = receiptSignedBytes(receipt.envelope.attestor, receipt.envelope.attested_at, stmt);
    if (!verifyBytes(receipt.envelope.attestor, signed, receipt.envelope.signature)) {
      return fail('S signature', 'receipt signature invalid over canonical(envelope minus signature, statement)');
    }
    pass('S signature');

    // T
    if (!(Number.isInteger(stmt.created_at) && Number.isInteger(stmt.closed_at) && stmt.created_at <= stmt.closed_at)) {
      return fail('T time bounds', 'created_at/closed_at not sane');
    }
    const dt = receipt.envelope.attested_at - stmt.closed_at;
    if (dt < -T_BACK_SKEW_MS || dt > T_FWD_LIMIT_MS) {
      return fail('T time bounds', `attested_at deviates ${dt}ms from closed_at (allowed [-${T_BACK_SKEW_MS}, ${T_FWD_LIMIT_MS}])`);
    }
    pass('T time bounds');

    // P
    const eDir = evidenceDir(cDir);
    const policyOnDisk = JSON.parse(readFileSync(join(eDir, 'policy.json'), 'utf8'));
    const policyHash = canonicalHash(policyOnDisk);
    if (policyHash !== stmt.policy_hash) {
      return fail('P policy pinned', `statement.policy_hash ${stmt.policy_hash} != hash of evidence policy copy ${policyHash}`);
    }
    if (!opts.trust.policies[policyHash]?.active) {
      return fail('P policy pinned', `policy hash ${policyHash} has no active pin`);
    }
    const manifest = JSON.parse(readFileSync(join(cDir, 'MANIFEST.json'), 'utf8'));
    if (manifest.policy_hash !== policyHash) {
      return fail('P policy pinned', 'manifest.policy_hash differs from evidence policy hash');
    }
    pass('P policy pinned');

    // M — mandate integrity + domain registry resolution (fail-closed)
    let mandate = null;
    let domain = null;
    if (manifest.files['mandate.json']) {
      mandate = JSON.parse(readFileSync(join(eDir, 'mandate.json'), 'utf8'));
      const sig = JSON.parse(readFileSync(join(eDir, 'mandate.sig.json'), 'utf8'));
      if (mandate.schema !== MANDATE_SCHEMA) return fail('M mandate integrity', 'mandate schema mismatch');
      const mHash = canonicalHash(mandate);
      if (stmt.mandate_hash !== mHash) {
        return fail('M mandate integrity', `statement.mandate_hash != recomputed hash of mandate.json (${mHash})`);
      }
      if (!opts.trust.attestors[sig.attestor_pubkey]?.active) {
        return fail('M mandate integrity', 'mandate attestor key has no active pin');
      }
      if (!verifyBytes(sig.attestor_pubkey, mandateMessage(mandate.case_id, mHash), sig.signature)) {
        return fail('M mandate integrity', 'mandate signature invalid over recomputed hash');
      }
      if (mandate.policy_hash !== stmt.policy_hash) {
        return fail('M mandate integrity', 'mandate.policy_hash differs from statement.policy_hash');
      }
      if (mandate.case_id !== stmt.case_id) return fail('M mandate integrity', 'mandate.case_id differs from statement.case_id');
      if (stmt.action_kind !== mandate.action.kind) {
        return fail('M mandate integrity', 'statement.action_kind differs from mandate.action.kind');
      }
      domain = domains[mandate.action.kind] ?? null;
      if (!domain) return fail('M mandate integrity', `action kind ${mandate.action.kind} is not a registered domain`);
    } else if (stmt.mandate_hash !== null) {
      return fail('M mandate integrity', 'statement carries a mandate_hash but no mandate.json exists');
    } else if (stmt.action_kind !== null) {
      // No mandate (INVALID_INTENT): action_kind may still be present when the
      // intent parsed far enough — resolve it if registered, tolerate unknown.
      domain = domains[stmt.action_kind] ?? null;
    }
    pass('M mandate integrity');

    // V
    const dirNames = readdirSync(eDir).sort();
    const manifestNames = Object.keys(manifest.files).sort();
    if (JSON.stringify(dirNames) !== JSON.stringify(manifestNames)) {
      return fail('V evidence integrity', `evidence set mismatch: dir [${dirNames.join(',')}] vs manifest [${manifestNames.join(',')}]`);
    }
    for (const name of manifestNames) {
      const st = lstatSync(join(eDir, name));
      if (st.isSymbolicLink() || !st.isFile()) return fail('V evidence integrity', `${name} is not a regular file`);
      const bytes = readFileSync(join(eDir, name));
      if (bytes.length !== manifest.files[name].bytes) return fail('V evidence integrity', `${name} byte length drift`);
      if (sha3Hex(bytes) !== manifest.files[name].sha3) return fail('V evidence integrity', `${name} sha3 drift`);
    }
    if (!manifest.files['errors.json']) return fail('V evidence integrity', 'errors.json missing (mandatory)');
    if (stmt.evidence_root !== canonicalHash(manifest)) {
      return fail('V evidence integrity', 'statement.evidence_root != sha3(canonical(manifest))');
    }
    pass('V evidence integrity');

    // J
    const scan = scanJournal(join(cDir, 'journal.jsonl'));
    if (!scan.ok) return fail('J journal chain', `chain broken at line ${scan.firstBad}: ${scan.error}`);
    if (scan.lines < 2) return fail('J journal chain', 'journal too short');
    const events = scan.entries.map((e) => e.event);
    if (events[0] !== 'case_opened') return fail('J journal chain', 'first journal event must be case_opened');
    if (events[events.length - 1] !== 'case_closed') return fail('J journal chain', 'last journal event must be case_closed');
    if (events.filter((e) => e === 'case_closed').length !== 1) return fail('J journal chain', 'case_closed must occur exactly once');
    if (scan.entries.some((e) => e.case_id !== stmt.case_id)) return fail('J journal chain', 'journal case_id drift');
    const closedEntry = scan.entries[scan.entries.length - 1];
    if (closedEntry.evidence_root !== stmt.evidence_root) {
      return fail('J journal chain', 'journal case_closed.evidence_root differs from statement.evidence_root');
    }
    if (closedEntry.outcome !== stmt.outcome) return fail('J journal chain', 'journal outcome differs from statement.outcome');
    pass('J journal chain');

    // E — execution artifact (domain check)
    if (manifest.files[ARTIFACT_FILE]) {
      const artifactHex = readFileSync(join(eDir, ARTIFACT_FILE), 'utf8').trim();
      if (stmt.execution_ref !== sha3Hex(Buffer.from(artifactHex, 'hex'))) {
        return fail('E envelope', `statement.execution_ref != sha3 of ${ARTIFACT_FILE} bytes`);
      }
      if (!domain) return fail('E envelope', 'artifact present but no domain resolvable for its check');
      const verdict = await domain.checkArtifact({
        artifactHex,
        stmt,
        mandate,
        evidenceDir: eDir,
        envelopeChecker: opts.envelopeChecker,
      });
      if (!verdict.ok) return fail('E envelope', verdict.detail);
    } else if (stmt.execution_ref !== null) {
      return fail('E envelope', `statement carries execution_ref but no ${ARTIFACT_FILE} exists`);
    }
    pass('E envelope');

    // D — derivation equality via THE shared builder + the domain's block
    const ctx = {
      case_id: stmt.case_id,
      outcome: stmt.outcome,
      outcome_detail: stmt.outcome_detail,
      mode: stmt.mode,
      created_at: stmt.created_at,
      closed_at: stmt.closed_at,
      producer_commit: stmt.context.producer_commit,
      runtime_version: stmt.context.runtime_version,
    };
    const view = loadEvidenceView(cDir);
    const domainBlock = domain ? domain.deriveDomainBlock(view) : null;
    const rederived = deriveReceiptStatement(view, ctx, domainBlock);
    if (canonicalize(rederived) !== canonicalize(stmt)) {
      return fail('D derivation equality', 'statement differs from deriveReceiptStatement() over the same evidence');
    }
    pass('D derivation equality');

    // O — outcome consistency: core contract, domain contract, subsets, then
    // domain extensions.
    const coreContract = coreRequiredFiles(stmt.outcome);
    const contract = coreContract ?? (domain ? domain.requiredFiles(stmt.outcome, stmt.mode) : null);
    if (!contract) return fail('O outcome consistency', `no evidence contract resolvable for outcome ${stmt.outcome}`);
    for (const r of contract.required) {
      if (!manifest.files[r]) return fail('O outcome consistency', `required evidence ${r} missing for outcome ${stmt.outcome}`);
    }
    for (const f of contract.forbidden) {
      if (manifest.files[f]) return fail('O outcome consistency', `forbidden evidence ${f} present for outcome ${stmt.outcome}`);
    }
    if (domain && !domain.allowedOutcomes.includes(stmt.outcome)) {
      return fail('O outcome consistency', `outcome ${stmt.outcome} not allowed for domain ${domain.kind}`);
    }
    if (mandate && stmt.mode !== mandate.mode) return fail('O outcome consistency', 'statement.mode differs from mandate.mode');
    if (stmt.mode === 'shadow' && stmt.outcome === 'EXECUTED') {
      return fail('O outcome consistency', 'mode shadow can never close as EXECUTED');
    }
    if (stmt.outcome === 'SHADOW_COMPLETED' && stmt.mode !== 'shadow') {
      return fail('O outcome consistency', 'SHADOW_COMPLETED requires mode shadow');
    }
    if (stmt.outcome === 'EXECUTED' && stmt.mode !== 'micro_live') {
      return fail('O outcome consistency', 'EXECUTED requires mode micro_live');
    }
    if (stmt.outcome === 'INVALID_INTENT') {
      if (stmt.mandate_hash !== null) return fail('O outcome consistency', 'INVALID_INTENT must not carry a mandate_hash');
      const intake = JSON.parse(readFileSync(join(eDir, 'intake-decision.json'), 'utf8'));
      if (intake.verdict !== 'reject') return fail('O outcome consistency', 'INVALID_INTENT requires a rejecting intake decision');
      if (intake.criterion !== stmt.outcome_detail.criterion) {
        return fail('O outcome consistency', 'intake criterion differs from outcome_detail.criterion');
      }
    }
    if (stmt.outcome === 'POLICY_REJECTED') {
      const decision = JSON.parse(readFileSync(join(eDir, 'policy-decision.json'), 'utf8'));
      if (decision.verdict !== 'reject') return fail('O outcome consistency', 'POLICY_REJECTED requires a rejecting policy decision');
      if (decision.criterion !== stmt.outcome_detail.criterion) {
        return fail('O outcome consistency', 'policy criterion differs from outcome_detail.criterion');
      }
    }
    if (domain) {
      const ext = domain.checkOutcomeExtensions({ stmt, evidenceDir: eDir, manifest });
      if (!ext.ok) return fail('O outcome consistency', ext.detail);
    }
    pass('O outcome consistency');

    return { rc: 0, results };
  } catch (err) {
    // Fail-closed: an unexpected exception is rc 2, never a silent pass.
    return { rc: 2, results, error: String(err) };
  }
}

// ===========================================================================
// ported from: src/executionCase/verifier/verify.ts (schema dispatcher)
// ===========================================================================

export async function verifyCase(cDir, opts) {
  let schema;
  try {
    const receipt = JSON.parse(readFileSync(join(cDir, 'receipt.json'), 'utf8'));
    schema = receipt.statement?.schema;
  } catch (err) {
    return { rc: 2, results: [], error: `cannot read receipt.json: ${String(err)}` };
  }

  if (schema === RECEIPT_SCHEMA_V1) {
    return verifyCaseV1(cDir, opts);
  }
  if (schema === 'cosmo.execution-case.receipt.v2') {
    return verifyCaseV2(cDir, opts);
  }
  // Fail-closed: an unknown schema is a REJECT with a named reason, never an
  // accept and never an exception. [ADR-001 decision 2.3]: the standalone
  // appends the ERROR_UNSUPPORTED_FORMAT tag to the internal verifier's text.
  return {
    rc: 1,
    results: [
      { criterion: 'S signature', ok: false, detail: `unknown receipt schema: ${String(schema)} [ERROR_UNSUPPORTED_FORMAT]` },
    ],
  };
}

